// Safe operating procedures. Each is a template to adapt to the site risk assessment; references map to India (OSH Code / state rules / BIS), OSHA and international standards.
window.PROCS = [
{id:"ptw",t:"Permit-to-Work (PTW) System",cat:"Management",tags:["Construction","Industrial","Chemical","Oil & Gas"],purpose:"Control non-routine, high-risk work by making hazards, precautions, isolations and authorisations explicit and signed before work starts, and by formally handing the area back afterwards.",scope:"Hot work, confined space entry, work at height, excavation, electrical (energised/HT), lifting with cranes, radiography, working on pressurised/chemical systems, roof work, demolition, vehicle entry to process areas, night work in restricted areas.",roles:["Permit Issuer / Area Authority (operations owner of the area)","Permit Receiver / Performing Authority (supervisor of the work party)","Isolating Authority (electrical/process)","Gas Tester (competent)","Safety Officer (audit, not routine signatory)","Fire Watch / Standby person where required"],hazards:["Undetected residual energy or pressure","Simultaneous operations (SIMOPS) interacting","Unclear boundaries or expiry leading to work continuing in changed conditions","Permit treated as paperwork rather than control"],pre:["Written PTW procedure approved by site management; permit types and forms defined (OISD-STD-105 / HSG250 as model)","Trained and authorised issuers/receivers (register of signatories with validity)","Permit board or e-PTW register visible at control point","Risk assessment / JSA attached for the task","Isolation certificates (electrical, process) and gas test where applicable"],steps:["Define the job: location (tag/grid), equipment ID, description, duration, number of persons.","Identify hazards with the receiver on site (walk-down), referencing the JSA/HIRA.","Specify precautions: isolations (lock/tag numbers), draining/purging, gas test limits, barricading, fire watch, rescue arrangements, PPE.","Check SIMOPS: cross-reference other live permits in the area; attach interlocks (e.g. no hot work while confined-space entry open below).","Issuer and receiver sign; display original at worksite, copy at control point/permit board.","Validity: typically one shift (max 8–12 h); extension only by re-verification and re-signature; gas test repeated at intervals and after breaks.","Supervisor carries out toolbox talk on permit conditions with the crew; crew signs attendance.","During work: receiver stays on site; stop work if conditions change (alarm, weather, new work nearby); issuer or safety officer audit a sample of permits daily.","Suspend permit for emergencies/alarms; re-validate before resumption.","Close-out: receiver confirms area clean, tools removed, guards/covers refitted; issuer inspects and signs close; de-isolation only after closure of all permits on that isolation.","File permits for the retention period (typically ≥ 1 year; 3 years for MAH units) and trend audit findings."],ppe:["As specified per permit type"],stop:["Gas reading beyond limits","Fire/gas alarm or site emergency","Permit expired or signatory absent","Unexpected energy source found"],records:["Permit forms (numbered), isolation register, gas-test log, permit audit sheet"],refs:{india:["Factories Act s.24 (devices for cutting off power) & s.37 (precautions before applying heat) – legacy basis; IS 17893:2023 Work Permit System code of practice (7 permit types); IS 11006 flashback arrestors","OSH Code 2020 s.6 (safe systems of work); Ch. XII hazardous processes","OISD-STD-105 Work Permit System (benchmark)","Factories Act s.36 / state Factories Rules – certificate for confined space; MSIHC Rule 4","Petroleum Rules 2002 Rule 118 – hot work in licensed premises","NBC 2016 Part 7 Sec. 4 – safety management"],ka:["Karnataka Factories Rules 1969 Rule 129 Schedule XVI (chemical works): written permits, blinding/disconnection, purging, gas-free certificate","Karnataka Factories Rules 1969 (confined space certificate; hot work in hazardous areas)","Karnataka BOCW Rules 2006 – site safety plan"],tn:["TN Factories Rules 1950 Rule 95 Schedule XVI (chemical works): written permits, mechanical isolation (blinding/disconnecting pipelines), gas-free certification by competent person","TN Factories Rules 1950 – Rule on dangerous fumes/certificate of safety","TN BOCW Rules 2006"],osha:["1910.146 (PRCS entry permit), 1910.147 (LOTO), 1926.1204, 1910.252/NFPA 51B hot work permit, NFPA 70E energised electrical work permit","OSHA PSM 1910.119(k) hot work permit"],intl:["HSE HSG250 Guidance on permit-to-work systems","ISO 45001 cl. 8.1 operational planning & control","ILO Code of Practice – Construction (permit systems)"]},checklist:"cl-hotwork"},

{id:"hotwork",t:"Hot Work (Welding, Cutting, Grinding, Brazing)",cat:"Fire & Emergency",tags:["Construction","Industrial","Chemical"],purpose:"Prevent fires, explosions and burns from sparks, open flame, hot surfaces and fumes.",scope:"Any work producing flame, sparks or temperatures able to ignite materials: arc/gas welding, oxy-fuel cutting, grinding, brazing, soldering, heat-gun bitumen work, thermite, powder-actuated tools.",roles:["Permit issuer","Hot-work supervisor","Welder/cutter (certified where structural/pressure welding)","Fire watch","Gas tester (process areas)"],hazards:["Ignition of combustibles within 11 m (35 ft) incl. hidden voids, floors below, ducts","Flammable vapour/gas (tanks, drums, drains, sewers)","Welding fumes (manganese, chromium VI, ozone), UV radiation, electric shock from welding sets","Cylinder incidents (acetylene flashback, oxygen enrichment)","Falls when welding at height; dropping hot slag on people below"],pre:["Hot-work permit issued (except in designated welding shops)","Gas test where any flammable may be present: 0% LEL for hot work in/near process plant (OISD); < 10% LEL general sites never acceptable for hot work — aim 0%","Fire extinguishers (min 2 × 9 kg DCP / CO2, or as permit) within reach; fire blanket; water supply","Combustibles removed to 11 m or covered with fire-resistant blankets; floor openings sealed; drains covered","Equipment inspected: cables, earth clamp, regulators, flashback arrestors (both ends), hoses, gauges"],steps:["Inspect area with issuer; identify combustibles, openings and adjacent work (SIMOPS).","Isolate/clean equipment to be welded: drain, purge, gas-free certificate for tanks/vessels (API 2015/2016 or OISD).","Establish exclusion/screens; post warning signs; protect people below with spark containment (fire blanket, sheeting).","Position fire watch with extinguisher; fire watch has no other duties during hot work and for ≥ 30 min after (NFPA 51B: 60 min typical in process areas; monitor up to 3 h).","Verify welder competence (IS 817 / structural code / IBR for pressure parts) and equipment earthing; welding return cable clamped close to the work.","Oxy-fuel: open cylinder valves slowly, acetylene ≤ 1 bar (15 psi), check leaks with soap solution, never oil on oxygen fittings, cylinders upright and secured, flashback arrestors fitted.","Perform work; re-test gas at intervals specified (typically every 2 h and after any break).","Local exhaust ventilation or fume extraction for stainless, galvanised, coated steel; respirator where LEV not feasible.","Stop at expiry; cool/quench slag; inspect area including below/behind; fire watch continues; sign permit close.","Report any flash fire or near miss; review JSA."],ppe:["Welding helmet (auto-darkening shade 9–13) / cutting goggles shade 5","Leather gauntlets, apron/jacket, FR coveralls","Safety boots, helmet (welding helmet compatible), ear plugs","Respirator (P2/P3 or PAPR for Cr VI) where needed"],stop:["LEL reading above 0% in process area / any detectable flammable gas","Fire watch unavailable","Combustibles cannot be removed or protected","Wet conditions with electric welding without protection"],records:["Hot-work permit, gas-test log, fire-watch log, welder certificates, equipment inspection tag"],refs:{india:["IS 17893:2023 hot-work permit; IS 11006 flashback arrestors; Factories Act s.37","OISD-STD-105; IS 818 safety in welding; IS 3016 fire precautions in welding/cutting; IS 2190 extinguishers","Petroleum Rules 2002 Rule 118; Gas Cylinders Rules 2016 (storage, handling)","Factories Act s.37/38; BOCW Central Rules 1998 fire protection chapter; NBC Part 7"],ka:["KA Rule 129 Sch. XVI hot-work protocol","Karnataka Factories Rules (fire precautions, flammable gas); KSFES NOC conditions"],tn:["TN Rule 95 Sch. XVI hot-work protocol","TN Factories Rules 1950; TN BOCW Rules 2006 (fire protection)"],osha:["1926 Subpart J (1926.350–354); 1910.252–255; NFPA 51B; 1910.119(k)"],intl:["HSE HSG250; EN ISO 9606 welder qualification; ILO CoP Construction"]},checklist:"cl-hotwork"},

{id:"confined",t:"Confined Space Entry",cat:"Industrial",tags:["Construction","Industrial","Chemical"],purpose:"Prevent asphyxiation, poisoning, fire/explosion, engulfment and entrapment in spaces not designed for continuous occupancy.",scope:"Tanks, vessels, silos, pits, manholes, sewers, pipelines, ducts, excavations deeper than 1.2 m with poor ventilation, boilers, tunnels, lift shafts, STP chambers, large-diameter piles.",roles:["Entry supervisor (permit issuer)","Entrants","Attendant/standby (continuous, outside, no other duty)","Gas tester","Rescue team (trained, equipment at point of entry)"],hazards:["Oxygen deficiency (< 19.5%) or enrichment (> 23.5%)","Toxic gases: H2S, CO, CO2, solvent vapours; flammable gas","Engulfment by solids/liquids; moving parts; heat; noise; limited egress","Hazards introduced by the work (welding fumes, coatings, inert gas purging)"],pre:["Confined-space register and signage at site; spaces classified (permit-required vs non-permit)","Written permit; isolation of inlets/outlets (blind/spade, lock, disconnect — not just valve closure)","Calibrated 4-gas detector (bump test same day); continuous monitoring","Forced ventilation (fresh air, not pure oxygen); lighting (24 V or intrinsically safe)","Rescue plan tested; retrieval system (tripod/winch) for vertical entry; communication method"],steps:["Identify and isolate all sources: energy (LOTO), process lines (blind), gravity/engulfment; drain, clean, purge and ventilate.","Gas-test from outside at top/middle/bottom before entry: O2 19.5–23.5%, LEL < 10% (0% for hot work), H2S < 10 ppm (TWA), CO < 25 ppm (ACGIH TLV; OSHA PEL 50 ppm). Record readings and time.","Entry supervisor issues permit listing hazards, limits, ventilation, PPE, rescue, duration.","Attendant posted at entrance with entrant log, communication (radio/voice/line), means to summon rescue; attendant never enters.","Entrants wear harness with lifeline attached to retrieval where feasible; carry personal gas monitor with alarm.","Continue ventilation; monitor continuously; re-test after breaks and at least every 2 h or as permit states.","No cylinders of compressed gas inside the space (except SCBA); torch hoses removed during breaks; no solvent use without respirator plan.","Evacuate immediately on alarm, ventilation failure, unusual odour/dizziness, or external emergency; never attempt rescue without SCBA/retrieval — most multiple fatalities are would-be rescuers.","On completion: head-count entrants out, remove tools, close permit, reinstate isolations only after permit closure, replace covers/guards.","Medical: workers fit for confined space (no claustrophobia, cardio-respiratory fitness)."],ppe:["Full-body harness with retrieval line","Personal 4-gas monitor","Helmet, boots, gloves, eye protection, coveralls","Respirator: SCBA/airline if atmosphere cannot be made safe (never a filter mask for O2 deficiency)"],stop:["Any gas reading outside limits","Attendant leaves post","Ventilation fails","Rescue team/equipment unavailable"],records:["Entry permit, gas-test log, entrant/attendant log, rescue drill records, detector calibration"],refs:{india:["Factories Act s.36/36A: certified manhole, purge/ventilate, test O2 & toxic gases, breathing apparatus with rescue lifeline; portable hand lamps ≤ 24 V; IS 11972 (sewer/confined space); IS 10245 Pts 1–4 (SCBA/airline); IS 17893:2023 Annex C permit & gas log (O2 19.5–23.5%, LEL < 5%, 0% hot work)","Factories Act 1948 s.36 (now OSH Code s.6 + state rules) – no entry unless certificate by competent person / breathing apparatus","OISD-STD-105 confined space permit; DGFASLI guidance on confined space entry; IS 15656 (hazard identification)","BOCW Central Rules 1998 (tunnelling, excavation ventilation)"],ka:["KA Rule 129 Sch. XVI: continuous standby attendant, forced ventilation, formal sign-off","Karnataka Factories Rules 1969 – precautions against dangerous fumes (certificate of safety)"],tn:["TN Rule 95 Sch. XVI Para 18: continuous standby attendant, forced ventilation, formal sign-off","TN Factories Rules 1950 – certificate of safety before entry (Form – verify)"],osha:["1910.146 Permit-Required Confined Spaces; 1926 Subpart AA (1926.1200–1213) construction; 1910.134 respirators","NFPA 350 Guide for Safe Confined Space Entry and Work; ANSI/ASSP Z117.1"],intl:["UK Confined Spaces Regulations 1997 & ACOP L101","ILO CoP Construction – confined spaces"]},checklist:"cl-confined"},

{id:"loto",t:"Lockout / Tagout – Control of Hazardous Energy",cat:"Electrical",tags:["Industrial","Construction","Chemical"],purpose:"Prevent unexpected start-up or release of stored energy (electrical, mechanical, hydraulic, pneumatic, chemical, thermal, gravity) during servicing and maintenance.",scope:"All maintenance, cleaning, un-jamming, inspection and set-up where a person could be injured by energisation or movement; includes process isolation (valves, blinds) and temporary site power.",roles:["Authorised employee (applies locks)","Affected employees (notified)","Isolating authority / electrical competent person","Supervisor verifying group lockout"],hazards:["Electrocution; crushing; entanglement; release of pressure/chemicals; falling parts","Stored energy: capacitors, springs, raised loads, flywheels, pressurised accumulators","Remote/auto restart via PLC, timers, interlocks","Multiple crews on one isolation (group lockout failures)"],pre:["Equipment-specific energy control procedures (ECP) written for each machine/system","Personal locks (one key), tags, hasps, lock boxes; isolation points labelled","Training: authorised, affected, other; annual periodic inspection of each ECP (OSHA 1910.147(c)(6))","Voltage tester (proved before/after on known live source); pressure gauge; blinding register"],steps:["Prepare: identify all energy sources from drawings/ECP; notify affected employees.","Shut down equipment using normal stop controls.","Isolate every energy source: open breakers/disconnects (not just pushbutton/emergency stop), close & lock valves, insert blinds, disconnect links.","Apply lock and tag at each isolation point; each worker applies own lock (group: lock box with master key).","Release/restrain stored energy: bleed pressure, discharge capacitors, block raised parts, let hot parts cool, restrain springs.","Verify zero energy: attempt start (then return control to OFF), test with proved voltage tester on all phases, check gauges/vents.","Perform work; if shifts change, outgoing lock removed only after incoming lock applied.","Restore: remove tools, reinstall guards, head-count, notify affected employees, remove locks (own only), re-energise with controlled start.","Lost key/absent worker: only supervisor per written procedure after verifying the person is not exposed and attempts to contact.","Review ECPs annually or on equipment change."],ppe:["Electrical: arc-rated clothing per incident energy (NFPA 70E), insulated gloves (IS 4770/EN 60903) with leather protectors, face shield","Standard site PPE"],stop:["Isolation cannot be verified","Lock/tag missing or tampered","Energy source not on drawings found"],records:["Isolation certificate, lock register, ECP documents, periodic inspection record, training"],refs:{india:["Factories Act s.24 striking gear/devices for cutting off power; IS 5216; IS 17893:2023 electrical permit","CEA Safety Regulations 2023 – work on electrical lines/apparatus (permit, earthing, isolation)","IS 5216 safety procedures in electrical work; Factories Act s.22 (work on or near machinery in motion) via state rules","OISD-STD-105 electrical isolation permit"],ka:["KA Rule 129 Sch. XVI isolation","Karnataka Factories Rules – precautions in handling machinery; CEIG Karnataka"],tn:["TN Rule 95 Sch. XVI isolation","TN Factories Rules 1950; CEIG Tamil Nadu"],osha:["1910.147 Control of Hazardous Energy; 1910.333 electrical safety-related work practices; 1926.417 lockout/tagging in construction","ANSI/ASSP Z244.1; NFPA 70E Art. 120 (electrically safe work condition)"],intl:["UK Electricity at Work Regs 1989 reg 12–14; HSE HSG85","ISO 14118 prevention of unexpected start-up"]},checklist:"cl-loto"},

{id:"wah",t:"Work at Height & Fall Protection",cat:"Construction",tags:["Construction","Industrial"],purpose:"Prevent falls of persons and objects from any height where a fall could cause injury (edges, openings, roofs, ladders, MEWPs, scaffolds, fragile surfaces).",scope:"All work where a person could fall from one level to another. Triggers: India BOCW/state rules & site practice commonly 1.8–2 m (verify state rule); OSHA construction 6 ft (1.8 m), general industry 4 ft (1.2 m); UK no minimum height.",roles:["Supervisor (plans WAH, rescue)","Competent person (inspects equipment, anchors)","Workers trained in WAH & harness use","Rescue team"],hazards:["Fall from unprotected edge, opening, fragile roof (AC sheets, skylights)","Ladder misuse; overreaching","MEWP tip-over, entrapment, catapult","Falling tools/materials onto people below","Suspension trauma after fall arrest"],pre:["Hierarchy applied: avoid WAH (prefab at ground) → collective protection (guardrails, nets, covers) → work-positioning/restraint → fall arrest (last resort)","Fall-protection plan with anchor points (≥ 22 kN / 5,000 lb or engineered), clearance calculation (free-fall + deceleration + harness stretch + safety ≈ 6 m for 1.8 m lanyard)","Harness (IS 3521 / EN 361), energy-absorbing lanyard (EN 355) or SRL (EN 360), inspected pre-use and 6-monthly by competent person; tagged","Rescue plan: retrieve suspended worker within 10–15 min (MEWP, rescue kit)","Weather check: no WAH in winds > 40 km/h (MEWP/crane limits per manufacturer), lightning, heavy rain"],steps:["Plan the task at ground level; select the safest access (mobile scaffold/MEWP preferred over ladders for prolonged work).","Install edge protection: top rail 0.95–1.1 m (OSHA 1.07 m ± 0.08), mid-rail, toe board ≥ 150 mm; cover and label floor openings (secured, load-rated); nets within 6 m below work surface.","Ladders: 4:1 angle, extend 1 m above landing, tied/footed, 3-point contact, no work from top 3 rungs; prohibit metal ladders near electricity.","Harness: 100% tie-off above shoulder where possible, twin-tail lanyards for moving, connect to rated anchor/lifeline — never to scaffold tubes without rated couplers or to rebar without engineered anchor.","MEWP: trained/licensed operator, daily check, outriggers on firm ground, harness with short restraint lanyard in boom-type, no climbing on rails, ground-rescue controls known.","Roof work: fragile-roof survey, crawling boards, edge protection, staging; no work on wet AC sheets.","Control dropped objects: tool lanyards, debris netting, exclusion zone below with barricade and signage.","Supervisor monitors; stop work if weather changes.","Rescue drill at project start and quarterly.","Daily visual check of harness/lanyard; remove from service after any fall arrest."],ppe:["Full-body harness with dorsal D-ring","Energy-absorbing lanyard/SRL","Chin-strapped helmet (EN 397 with chin strap / IS 2925)","Non-slip boots; gloves; hi-vis"],stop:["No rated anchor available","Wind/lightning","Harness damaged or uninspected","Rescue plan not in place"],records:["WAH permit, harness inspection register (6-monthly), scaffold tags, MEWP daily checks, training & rescue drill records"],refs:{india:["Factories Act s.32 (fencing/handrails/harness where liable to fall > 2 m; 1.8 m practice); IS 3521:2021 Pts 1–5 (harness, lanyards/absorbers, SRL, vertical rails, connectors); IS 5175 & IS 11057 safety nets; IS 17893:2023 WAH permit","BOCW Central Rules 1998 (safety belts, nets, guardrails, ladders); state BOCW Rules KA/TN 2006","IS 3521 (harness), IS 3696 Pt 2 (ladders), IS 4014, IS 13416 Pt 1 (falls); NBC Part 7","OSH Code 2020 s.6; Factories Act s.32/33 (floors, pits, openings)"],ka:["Karnataka Factories Rules Rule 65 & Rule 88B; Karnataka BOCW Rules 2006 (fall protection, scaffold inspection, safety nets)","Karnataka BOCW Rules 2006 – fall prevention, ladders, hoists"],tn:["TN Factories Rules Rule 61-O & 61-B (certified harnesses, helmets with nape straps, competent-person inspection of belts); TN BOCW Rules 2006 Rules 188–205 (scaffolds & ladders)","TN BOCW Rules 2006 – fall protection"],osha:["1926 Subpart M (1926.500–503); 1926 Subpart X ladders; 1926.453 aerial lifts; 1910 Subpart D (walking-working surfaces) and I; ANSI/ASSP Z359"],intl:["UK Work at Height Regulations 2005; HSE INDG401; EN 13374 edge protection; ISO 16024 anchors","ILO CoP Construction ch. on work at height"]},checklist:"cl-wah"},

{id:"scaffold",t:"Scaffolding – Erection, Inspection, Use & Dismantling",cat:"Construction",tags:["Construction","Industrial"],purpose:"Provide a safe working platform and prevent scaffold collapse, falls and falling objects.",scope:"Tube-and-coupler, cuplock/system, mobile tower, cantilever, suspended (swing-stage) and bamboo scaffolds (bamboo discouraged; if used, per IS 3696 with competent supervision).",roles:["Scaffold designer (for non-standard/over 30 m/loads)","Scaffold supervisor (competent)","Trained scaffolders","Scaffold inspector (competent person, independent of erector where possible)"],hazards:["Collapse: inadequate ties, foundations, bracing, overloading","Falls during erection/dismantling (no guardrails yet)","Incomplete platforms, gaps, missing toe boards","Proximity to overhead lines; mobile tower movement with persons aboard"],pre:["Design drawing or standard configuration (manufacturer/IS 4014/BS EN 12811); load class defined (light 1.5 kN/m², medium 2.0, heavy 3.0 — verify)","Materials inspected: tubes straight (no corrosion/dents), couplers tested, boards sound, base plates/sole boards","Ground bearing assessed; sole boards on soft ground","Tie pattern (typically every 4 m vertically × 6 m horizontally for sheeted less) and bracing","Scaffold tag system (Green = safe, Red = do not use) at each access"],steps:["Erect progressively with scaffolders tied off (advanced guardrail or harness to independent anchor); use ladder access bays.","Standards plumb on base plates; ledgers level; transoms at lift height; lift height ≤ 2 m; bay width adequate (boards ≥ 600 mm for working platform, 5 boards for material).","Fit ties as erection proceeds (through ties/box ties/anchor ties); never remove ties for façade work without replacing.","Platform: close-boarded, boards overhang supports 50–150 mm, no trip gaps; guardrails (top 0.95–1.0 m, mid), toe boards; brick guards where material stacked.","Access: internal ladders through trapdoors, or stair towers; no climbing frames.","Inspect before first use, after any alteration, after adverse weather, and at least every 7 days; record on tag and register.","Load control: posted SWL; no accumulation of debris; distribute materials over standards.","Mobile towers: height ≤ 3× base (outdoor) / 3.5× (indoor) unless outriggers; lock castors; never move with people/materials aloft; check overhead lines.","Suspended scaffolds: secondary safety line per worker, independent of suspension rope; daily rope/hoist check.","Dismantle in reverse order, lowering components (no throwing); keep ties until last; barricade below."],ppe:["Harness & lanyard (scaffolders), helmet with chin strap, gloves, boots, hi-vis"],stop:["Red tag / no tag","Missing ties/bracing or guardrails","Wind > 40 km/h or lightning","Overhead line within 3 m (LV) / 6 m+ (HT) without authority"],records:["Scaffold design, inspection register (7-day), tags, scaffolder competence certificates, material inspection"],refs:{india:["IS 5175 / IS 11057 safety nets; IS 13415 protective barriers; SP 70","IS 3696 Pt 1 (scaffolds code of safety), IS 4014 Pt 1 & 2 (steel tubular scaffolding), IS 2750 (steel scaffolding)","BOCW Central Rules 1998 & KA/TN BOCW Rules 2006 – scaffolding chapter (inspection, platforms, guardrails)","NBC 2016 Part 7"],ka:["Karnataka Factories Rules Rule 88B; Karnataka BOCW Rules 2006","Karnataka BOCW Rules 2006 – scaffolds"],tn:["TN BOCW Rules 2006 Rules 188–205","TN BOCW Rules 2006 – scaffolds; TN CDBR 2019 site conditions"],osha:["1926 Subpart L (1926.450–454): competent person, 4:1 rule, guardrails > 10 ft, planking, access; App. A specifications"],intl:["BS EN 12811-1, EN 12810 (system scaffolds); UK NASC TG20/SG4; HSE guidance on scaffold inspection","ILO CoP Construction – scaffolds"]},checklist:"cl-scaffold"},

{id:"excavation",t:"Excavation, Trenching & Underground Utilities",cat:"Construction",tags:["Construction"],purpose:"Prevent cave-ins, utility strikes, falls into excavations, flooding, hazardous atmospheres and struck-by incidents from plant.",scope:"All excavations, trenches, pits, shafts, basements; manual and machine digging; working near underground services (power, gas, water, telecom, sewer) and overhead lines.",roles:["Competent person (daily inspection, soil classification, protective system)","Excavation supervisor","Banksman/spotter for plant","Utility locator"],hazards:["Collapse of sides (1 m³ of soil ≈ 1.5–2 t); undermining of adjacent structures/roads","Striking live cables/gas mains; overhead line contact by excavator boom","Falls into excavation; persons struck by bucket/reversing plant","Water ingress, hazardous gases (sewer/landfill), falling spoil/materials","Excavation collapse during monsoon (Karnataka/TN June–Dec rains)"],pre:["Permit-to-dig after utility survey: drawings from BESCOM/TANGEDCO, gas (GAIL/IGL/AG&P), water boards, telecom; cable locator scan (CAT & Genny) and trial pits by hand","Soil classification by competent person; protective system chosen: sloping/benching (angle per soil, 1:1 for Type B equivalent; 1.5:1 for sand), shoring, trench box; design by engineer for depth > 6 m (OSHA > 20 ft)","Protective system required for depth ≥ 1.5 m (India BOCW/IS 3764) / ≥ 5 ft (OSHA) unless solid rock","Dewatering plan; discharge consent; edge protection and access ladders (within 7.5 m / 25 ft travel)","Spoil and plant kept ≥ 1 m (OSHA 2 ft min; good practice ≥ depth of trench) from edge; stop blocks for vehicles"],steps:["Mark services on ground (paint/flags); hand-dig within 0.5–1 m of marked services; treat all cables as live.","Set exclusion zone; hard barricade (not tape alone) ≥ 1.2 m high around open excavation, lighting at night, signage; cover small pits.","Excavate with banksman controlling plant; no one in bucket swing radius; machine at least 1 m from edge, on firm ground; overhead-line clearance maintained (≥ 3 m LT, ≥ 6 m HT — per CEA/Reg; use goal posts).","Install shoring/box progressively — never enter unprotected trench > 1.5 m; trench box top ≥ 0.45 m above trench bottom for sloped portion.","Daily inspection by competent person before each shift, after rain, blasting, vibration or any change; record (Form/register).","Provide ladders every 7.5 m, extending 1 m above surface, secured; separate pedestrian walkways with handrails for crossings.","Test atmosphere in excavations > 1.2 m deep where gases possible (near sewers, landfills, fuel tanks) — treat as confined space if criteria met.","Monsoon controls: pumps on standby, berms to divert runoff, re-inspect after every rain, stop work and evacuate in heavy rain.","Backfill in layers; compaction with plant kept clear of persons; reinstate surfaces.","Near existing structures: underpinning design, settlement monitoring, no excavation below foundation influence line without engineer's approval."],ppe:["Helmet, boots, hi-vis, gloves, eye protection; harness for shaft work; gas monitor where required"],stop:["Unprotected trench > 1.5 m with persons inside","Water accumulating; cracks or tension cracks on surface","Unexpected service found","Spoil within 1 m of edge or plant near edge on soft ground"],records:["Permit-to-dig, utility clearance, daily excavation inspection register, soil classification, shoring design"],refs:{india:["SP 70 (2001) BIS Handbook on Construction Safety Practices; IS 13415/13416","IS 3764 Excavation work – code of safety; IS 4081 blasting; BOCW Central Rules 1998 excavation & tunnelling chapter; KA/TN BOCW Rules","CEA Safety Regulations 2023 – clearances from overhead/underground lines; Electricity Act s.161 accident reporting","NBC Part 7; IRC:SP:55 (roadworks traffic)"],ka:["BOCW (Karnataka Amendment) Rules 2024","Karnataka BOCW Rules 2006; BESCOM/BWSSB/GAIL utility permission (Bengaluru)"],tn:["TN BOCW Rules 2006 (excavation, cofferdams)","TN BOCW Rules 2006; TANGEDCO/CMWSSB utility permissions"],osha:["1926 Subpart P (1926.650–652 & App. A–F): soil types A/B/C, sloping tables, protective systems ≥ 5 ft, ladder ≥ 4 ft, PE design > 20 ft, daily inspection"],intl:["HSE HSG47 Avoiding danger from underground services; HSE HSG185 excavations","ILO CoP Construction – excavations"]},checklist:"cl-excavation"},

{id:"lifting",t:"Lifting Operations, Cranes & Rigging",cat:"Construction",tags:["Construction","Industrial"],purpose:"Prevent dropped loads, crane overturning/collapse, contact with power lines, crushing and struck-by incidents.",scope:"Mobile/crawler/tower cranes, EOT cranes, hydra (pick-and-carry), hoists, winches, chain blocks, forklifts used for lifting, material and passenger hoists, lifting gear (slings, shackles, eyebolts, spreader beams).",roles:["Appointed person / lifting supervisor (plans lift)","Crane operator (licensed/competent; HMV licence for mobile crane)","Rigger/slinger (trained)","Signaller/banksman","Competent person for test & examination"],hazards:["Overload, out-of-radius, ground failure under outriggers, wind","Rigging failure, uncontrolled load swing, tag-line absence","Contact with overhead lines (fatal common cause in India)","Hydra cranes used beyond capacity on slopes; persons riding loads/hooks","Falling objects from height; crushing in pinch points"],pre:["Lifting plan (routine or complex): load weight (verified, +10% rigging), radius, chart capacity (≤ 75–85% utilisation for critical lifts), ground bearing pressure, outrigger pads, exclusion zone","Crane: valid test certificate (12-monthly by competent person, India; 'thorough examination' LOLER), load chart in cab, LMI/ASLI functional, anemometer; daily pre-use check","Lifting gear: colour-coded, SWL marked, 6-monthly (accessories) / 12-monthly (appliances) examination; register","Permit for lifts near lines, over public areas, tandem lifts, > 75% capacity, personnel baskets (last resort, engineered)","Weather: stop at wind ≥ 9–10 m/s (manufacturer), lightning, poor visibility"],steps:["Appointed person surveys: ground, lines, obstructions, laydown; prepares lift plan and JSA; toolbox talk.","Position crane: level (≤ 1%), outriggers fully extended on pads/mats sized for bearing pressure; distance from excavation edge ≥ 1.5 × depth or shored.","Rig load: correct sling angle (≤ 90° included; capacity reduces as angle widens), edge protectors, shackles pinned, hooks with latches, tag lines (2 for long loads).","Signaller only person giving signals (standard hand signals IS 13367 / ASME B30.5); radio for blind lifts.","Trial lift: raise 100–200 mm, check balance, brakes, LMI; then lift smoothly; no load over persons; nobody under suspended load.","Exclusion zone barricaded; load landed on stable dunnage; slings released only when load stable.","Power lines: maintain ≥ 3 m (up to 11 kV) / 6 m (above 11 kV) or per CEA table; use dedicated spotter; de-energise where possible (OSHA Table A: 10 ft to 50 kV, +0.4 in per kV).","Hydra/pick-and-carry: only on firm level ground, boom retracted, load close to ground, no persons within 5 m, never exceed chart; banned for lifts near lines.","Material/passenger hoists: licensed where state lifts act applies; gates interlocked, SWL posted, daily checks, no persons on material hoist.","Record lift, incidents and near misses; review plan for repeat lifts."],ppe:["Helmet, boots, gloves, hi-vis, eye protection; harness for working on crane/at height"],stop:["LMI alarm or load unknown","Wind beyond limit","Ground sinking/outrigger lifting","Line clearance cannot be maintained","Signaller loses sight/comms"],records:["Lift plans, crane/gear test certificates (Form per state rules), daily checks, rigging register, operator licences"],refs:{india:["IS 2762 wire-rope slings","Factories Act s.28/29 (hoists, lifting machines – now OSH Code s.6 + state rules) – 12-monthly test by competent person","BOCW Central Rules 1998 – lifting appliances & gear chapter; KA/TN BOCW Rules 2006","IS 13367 Pt 1 safe use of cranes; IS 4573 mobile cranes; IS 807, IS 3177; IS 2266/2762 wire ropes & slings; IS 6216 chain slings","CEA Safety Regulations 2023 clearances; state lifts & escalators acts (hoists)"],ka:["KA Rules 58 & 59 (Forms 6 & 7): annual certification of hoists, lifts, EOT cranes, chain pulley blocks, wire ropes via e-Surakshate","Karnataka Factories Rules 1969 (lifting machines/tackles test); Karnataka Lifts Act 2012 (hoists where applicable)"],tn:["TN Rules 55 & 55A (Forms 8 & 9): annual examination of hoists, lifts, cranes, slings, tackles by DISH-approved competent person","TN Factories Rules 1950 Rule 55A; TN Lifts and Escalators Act 1997"],osha:["1926 Subpart CC (1926.1400–1442): operator certification, ground conditions, assembly, power-line clearance, signal person; 1926.251 rigging; 1910.179/180/184; ASME B30 series"],intl:["UK LOLER 1998; BS 7121 safe use of cranes; ILO CoP Construction – lifting appliances"]},checklist:"cl-lifting"},

{id:"demolition",t:"Demolition & Dismantling",cat:"Construction",tags:["Construction"],purpose:"Prevent premature collapse, falls, falling debris, utility incidents, asbestos/lead exposure and harm to the public during demolition.",scope:"Partial/total demolition of buildings, structures, chimneys, tanks; mechanical, manual, cut-and-lift, deconstruction; excludes blasting (see explosives).",roles:["Demolition engineer (structural survey, method statement)","Demolition supervisor","Asbestos surveyor/removal contractor (licensed where applicable)","Plant operators; banksmen"],hazards:["Unplanned collapse, loss of stability as members removed","Falls through openings/weakened floors","Dust (silica), asbestos (AC sheets, pipe lagging, gaskets), lead paint, PCBs","Live services, gas, chemical residues in tanks","Public and adjacent property; traffic; noise/vibration"],pre:["Structural survey & demolition method statement (sequence, props, exclusion zones) by competent engineer; local-body demolition permission","Pre-demolition hazardous materials survey (asbestos, lead, PCBs, residual chemicals, UST); removal before demolition by licensed agency; asbestos waste to authorised TSDF","All services disconnected and capped (electricity, gas, water, sewer, telecom); temporary supply for site separately","Hoarding/scaffold with debris netting, fans/catch platforms; pedestrian diversion; dust suppression; C&D waste plan (2025 Rules) with destination facility","Notify neighbours; vibration/noise monitoring near sensitive structures"],steps:["Establish exclusion zone ≥ 1.5 × height of structure for mechanical demolition (or as engineer specifies); gates manned.","Remove salvageable/hazardous items first; strip top-down for manual demolition; never undermine or remove load-bearing elements before upper loads removed.","Mechanical demolition: high-reach/excavator with operator cab FOPS, water spray for dust, no one within reach radius; drop zones planned.","Floors: do not overload with debris; use chutes (enclosed) for debris; openings guarded.","Monitor stability continuously; stop if unexpected movement, cracks; props as per plan.","Hot cutting of tanks/vessels only after gas-free certificate.","Handle asbestos-cement sheets whole (no breaking), wet, double-bagged, labelled, PPE (P3 respirator, disposable coveralls), decontamination; medical surveillance per state rules Schedule (TN Sch. XX asbestos 2025).","Debris transport covered; weighbridge/manifest for C&D waste; concrete to recycler.","End of day: secure site, fencing, lighting, no partially demolished unstable elements left.","Final: inspect, remove props safely, clear site, close permits."],ppe:["Helmet, boots, gloves, eye protection, hi-vis, P2/P3 dust respirator; harness for edge work; hearing protection"],stop:["Unexpected movement/cracking","Asbestos found unplanned","Service found live","Dust escaping site / public exposure"],records:["Structural survey, method statement, hazardous-materials survey, asbestos removal records, C&D waste manifests, demolition permission"],refs:{india:["SP 70; IS 13415 protective barriers","IS 4130 Demolition of buildings – code of safety; NBC 2016 Part 7 Sec. 3; BOCW Central Rules 1998 demolition chapter; KA/TN BOCW Rules","Environment (C&D) Waste Management Rules 2025; Hazardous & Other Wastes Rules 2016 (asbestos waste); state Factories Rules asbestos schedules","Municipal demolition permission (BBMP / Greater Chennai Corporation)"],ka:["BOCW (Karnataka Amendment) Rules 2024; BBMP/BDA bylaws","Karnataka BOCW Rules 2006; BBMP building bye-laws; KSPCB dust norms"],tn:["TN BOCW Rules 2006 (demolition); CMDA/DTCP","TN BOCW Rules 2006; TN CDBR 2019; TN Factories Rules Sch. XX (asbestos, 2025); TNPCB"],osha:["1926 Subpart T (1926.850–860) demolition; 1926.1101 asbestos; 1926.62 lead; 1926.1153 silica"],intl:["BS 6187 Code of practice for full and partial demolition; UK Control of Asbestos Regulations 2012; ILO CoP Construction – demolition"]},checklist:"cl-demolition"},

{id:"electrical",t:"Electrical Safety – Site Temporary Power, LV/HT Work & Overhead Lines",cat:"Electrical",tags:["Construction","Industrial"],purpose:"Prevent electrocution, arc flash, electrical fires and contact with overhead/underground lines.",scope:"Temporary site distribution (DBs, generators, cables), portable tools, lighting, welding sets; maintenance on LV/HT systems; work near live overhead lines; substations.",roles:["Licensed electrical supervisor/wireman (state licence)","Competent person for HT (authorised by CEIG/utility)","Permit issuer for electrical work","All workers (awareness)"],hazards:["Shock/electrocution from damaged cables, improper joints, no RCD, wet conditions","Arc flash during switching/testing on energised boards","Overhead line contact by cranes, concrete pump booms, tipper bodies, scaffold tubes, ladders","Fire from overloaded temporary wiring; DG set hazards (fuel, CO, noise)"],pre:["Temporary electrical layout approved; all circuits protected by 30 mA RCD (ELCB) at DB; earthing per IS 3043 tested (< 1 Ω typical site target) and re-tested quarterly","Industrial plugs/sockets (IS/IEC 60309), armoured/ double-insulated cables, cables overhead or protected, no joints by taping","DBs lockable, labelled, IP rated, accessible, with fire extinguisher (CO2) nearby; monthly inspection tag","Portable tools 110 V CTE or double-insulated 230 V with RCD; inspection/test (PAT) 3-monthly; register","Overhead lines surveyed; goal posts/barriers at crossings; clearance per CEA regulations; shutdown/shrouding arranged with utility where needed"],steps:["Energise only through approved DBs by licensed electrician; no direct connection to live terminals.","Daily visual check of cables, plugs, RCD test button weekly (record).","Work on electrical equipment dead: isolate, lock, test dead with proved tester, earth where HT; permit-to-work for HT (utility/CEIG format).","Energised work only where unavoidable, by qualified person under energised-work permit with arc-flash PPE and boundaries (NFPA 70E) – never alone.","Keep plant, scaffold, ladders and materials outside line-clearance zones; crane operators briefed; spotter assigned; use insulated link stick where authorised.","Wet weather: suspend outdoor electrical work; protect DBs; raise cables.","DG sets: earthed (2 earth pits), acoustic enclosure (75 dB(A) @ 1 m), exhaust away from work areas, fuel in bunded tank (PESO licence if > 2,500 L Class B), no refuelling while running, fire extinguishers.","Lighting: 24 V in confined/wet areas; task lighting ≥ 100 lux general, 200 lux work areas (IS 3646).","Report every shock/arc-flash as incident; notify Electrical Inspector within 48 h for reportable electrical accidents (fatal immediately).","Lightning: suspend WAH/crane work; LPS on tall structures (IS/IEC 62305)."],ppe:["Insulated gloves (class per voltage) with leather over-gloves, arc-rated FR clothing, face shield/hood, insulated tools, safety boots (electrical hazard rated), helmet (non-metallic)"],stop:["Missing/failed RCD","Damaged cable or exposed conductors","Plant within line-clearance zone","Rain on exposed temporary installation"],records:["Temporary electrical layout, earth-test records, RCD test log, PAT register, HT permits, electrician licences, DG set consent"],refs:{india:["IS 15652 insulating mats (replaces IS 5424) in front of all LT/HT panels; IS 3043 double earthing & earth-pit logging; IS/IEC 60079 Zones 0/1/2; IS 17893:2023 electrical permit","Electricity Act 2003 s.53/161; CEA (Measures relating to Safety and Electric Supply) Regulations 2023 (clearances, earthing, work on lines, accident notice)","IS 3043 earthing; IS 732 wiring; IS 5216 electrical work safety; IS 13252; IS/IEC 60309 plugs; IS 3646 lighting; IS 2309/IEC 62305 lightning","BOCW Central Rules 1998 electrical chapter; KA/TN BOCW Rules; state wireman/supervisor licensing rules"],ka:["CEIG Karnataka periodic inspections; DG set approvals","CEIG Karnataka approvals; BESCOM line shutdown/ shrouding requests; Karnataka Electricity Reforms Act licensing"],tn:["CEIG Tamil Nadu periodic inspections; DG set approvals","CEIG Tamil Nadu approvals; TANGEDCO shutdown/ shrouding; TN Electrical Licensing Board (wireman/supervisor)"],osha:["1926 Subpart K (1926.400–449): GFCI or AEGCP; 1926.416 line clearance; 1910.303–335; 1910.269 power generation/transmission; NFPA 70E; NFPA 70 (NEC) Art. 590 temporary installations"],intl:["UK Electricity at Work Regs 1989; BS 7671 §704 construction sites (110 V CTE); HSE HSG141 electrical safety on construction sites; GS6 overhead lines; IEEE 1584"]},checklist:"cl-electrical"},

{id:"chemicals",t:"Hazardous Chemical Handling, Storage & SDS Management",cat:"Chemical",tags:["Chemical","Industrial","Construction"],purpose:"Prevent exposure, fire/explosion, spills and environmental release from hazardous chemicals (solvents, acids/alkalis, gases, fuels, admixtures, epoxies, pesticides, cement).",scope:"Receipt, storage, transfer, use, waste and emergency handling of all hazardous chemicals; threshold-quantity screening against MSIHC Schedules; dangerous-goods transport.",roles:["Chemical/process owner","Stores in-charge","Safety officer / EHS","Occupational health physician (surveillance)","Emergency response team"],hazards:["Inhalation/skin/eye exposure; chronic effects (CMR, sensitisers – isocyanates, chromates)","Fire/explosion of flammables; incompatibles (oxidisers + flammables, acids + cyanides/hypochlorite)","Spills to drains/soil; toxic gas release (chlorine, ammonia, H2S)","Pressure/temperature runaway; static ignition during transfer"],pre:["Chemical inventory with GHS classification, quantities, locations; screened against MSIHC Sch. 1/2/3 thresholds (MAH status → site notification, safety report, on-site plan)","16-section SDS (ISO 11014/UN GHS) for every chemical, available at point of use in local language (Kannada/Tamil summaries); MSDS per MSIHC Rule 17 format","Storage design: segregation matrix, bunding (110% of largest container), ventilation, flameproof electricals in Zone 1/2 (IEC 60079), earthing/bonding for Class A/B liquids, eyewash/shower within 10 s / 15 m","PESO licence for petroleum Class A/B above thresholds; gas cylinders store; SPCB consent/HW authorisation","Spill kits, PPE matrix, exposure monitoring plan (PELs per Factories Act Sch. II / OSH rules; TLVs)"],steps:["Receipt: verify label, SDS, container integrity; reject damaged; TREM card for transport; unloading with bonding and bunded area.","Store by compatibility class, not alphabetically; flammables in cabinets (NFPA 30/IS) ≤ 250 L per cabinet (verify) or dedicated store; cylinders upright, chained, caps on, oxidisers 6 m from fuel gases.","Label all secondary containers (name, hazard, date); never use food/water containers.","Transfer: closed systems/pumps where possible; grounding clips; drum pump; no siphoning by mouth; LEV for solvents; work-area monitoring (PID/detector tubes) for high-risk tasks.","Use: follow SDS Sec. 7/8; PPE per matrix (chemical-resistant gloves with breakthrough time, goggles/face shield, apron, respirator cartridge type); hygiene – no eating/smoking, wash before breaks.","Health surveillance: pre-employment & periodic medicals for dangerous operations (lead, chrome, solvents, isocyanates, asbestos, silica) by certifying surgeon; records.","Waste: segregate hazardous waste (used oil, solvent, contaminated PPE, empty drums) → labelled, ≤ 90 days storage, manifest to authorised recycler/TSDF; Form 4 annual return.","Spill: evacuate, isolate ignition, PPE, contain (booms/absorbent), collect, report to SPCB if beyond site/ significant (HOWM Rule 23 Form 11); EPA s.9 duty to report forthwith.","MAH units: on-site emergency plan rehearsed every 6 months; off-site plan with District Collector; mock drill with District Crisis Group yearly; safety audit annually; safety report update every 3 years.","Management of change for any new chemical/process (see MoC procedure)."],ppe:["Per SDS Sec. 8: chemical goggles, face shield, nitrile/butyl/viton gloves, chemical apron/suit, respirator (OV/AG cartridges or SCBA), safety boots"],stop:["Unlabelled container","Incompatible storage found","Leak/odour beyond control","Missing SDS for new chemical"],records:["Chemical inventory, SDS register, MSIHC site notification/safety report, exposure-monitoring results, medical records (retained ≥ 30–40 yrs for carcinogens – verify), HW manifests & returns, spill reports, drill records"],refs:{india:["Factories Act Ch. IVA ss.41A–41H (Site Appraisal Committee, disclosure, on-site plan, OHC, Second Schedule PELs); IS 17859 (GHS classification, labelling, SDS); IS 4209; IS 11457 Pt 1; IS 14489; PESO Southern Circle Chennai (TN) / Sub-circle Mangaluru-Bengaluru (KA)","MSIHC Rules 1989; Chemical Accidents (EPPR) Rules 1996; Public Liability Insurance Act 1991","Factories Act Ch. IVA / Sch. II PELs (via state rules & OSH Code Ch. XII); OSH Code s.6, s.12 (notifiable diseases)","Hazardous & Other Wastes Rules 2016; EP Act s.9; Water/Air Acts (SPCB consent)","Petroleum Rules 2002; Gas Cylinders Rules 2016; SMPV(U) 2016; CMV Rules 129–137 (TREM card, driver training)","IS/ISO 11014 SDS; IS 15656 HAZOP (hazard identification); IS 4379 cylinder colour"],ka:["KA Rules 88-A to 88-P (H&S policy, OHC, ambulance van, Safety Committee 88-B, chemical disclosure); KA Rule 129 dangerous operations (26+ schedules); Major Accident Hazards Control (Karnataka) Rules 1994","Karnataka Factories Rules 1969 dangerous operations schedules & Rule 129; KSPCB HW authorisation; DFBISH MAH registry; Karnataka Safety Audit Rules 2024"],tn:["TN Rules 61-F to 61-T (site appraisal 61-F, SDS 61-H, OHC & ambulance van 61-O/61-P, decontamination 61-Q, medical exams 61-N); TN Rule 95 dangerous operations (30+ schedules incl. Sch. XVI chemical works); TN CIMAH Rules 1994 (third-party audits, off-site inputs)","TN Factories Rules 1950 Rule 95 Schedules (incl. Sch. XX asbestos 2025); DISH TN MAH units; TNPCB HW authorisation"],osha:["1910.1200 HazCom (GHS); 1910.119 PSM; 1910.120 HAZWOPER; 1910.1000 PELs; 1910.106 flammable liquids; 1926.59/1926.55/1926.152; NFPA 30, NFPA 400"],intl:["UN GHS; REACH/CLP; COSHH 2002; Seveso III / COMAH; ILO C170 & C174; CCPS RBPS"]},checklist:"cl-chemical"},

{id:"fire",t:"Fire Prevention, Protection & Evacuation",cat:"Fire & Emergency",tags:["Construction","Industrial","Chemical"],purpose:"Prevent fires, limit spread, and ensure everyone can evacuate safely; meet Fire NOC conditions.",scope:"Factories, warehouses, construction sites (incl. labour colonies), site offices, fuel stores, hot-work areas, electrical rooms.",roles:["Fire safety officer / fire warden per floor/zone","Emergency response team (trained in extinguishers/hydrants)","Security (gate, assembly point control)","Maintenance (fire system AMC)"],hazards:["Electrical faults, hot work, smoking, cooking in labour camps, LPG, flammable storage, combustible waste accumulation, arson","Blocked exits, locked doors, storage in staircases","Construction sites: formwork timber, shuttering oil, bitumen, cylinders, temporary wiring","High-rise under construction without fire-fighting infrastructure"],pre:["Fire risk assessment; fire plan with zoning, exits, assembly points; Fire NOC (KSFES/TNFRS) where applicable","Extinguishers selected and placed per IS 2190 (travel ≤ 15 m Class A / ≤ 10–15 m Class B; 1 per 100–200 m²), inspected monthly, serviced annually, hydrostatic test per schedule","Hydrant/sprinkler/alarm systems maintained (NFPA 25 / IS 13039, IS 15105, IS 2189); fire pump weekly test","Emergency lighting, exit signs, clear escape routes ≥ 1 m, doors opening outward; no locks during occupancy","Trained fire wardens; evacuation drill every 6 months (every 3 months for hazardous units); mutual-aid agreements"],steps:["Housekeeping daily: combustible waste removed, no accumulation under stairs/near exits; oily rags in metal bins with lids.","Control ignition: smoking only in designated areas; hot-work permit; electrical inspections; no open fires in labour camps – provide LPG cooking areas with extinguishers.","Flammables: minimum quantities at point of use, in approved cabinets; cylinders stored outdoors in cages, segregated; fuel in bunded tanks away from buildings (≥ 6 m).","Construction: progressive installation of fire standpipe/risers as floors rise (NBC/NFPA 241 – wet riser charged within 2 floors of top), temporary extinguishers each floor, access for fire tender maintained, no storage blocking stairs.","Detection/alarm tested weekly; manual call points; PA system; alarm sound known to all.","On alarm: raise alarm (shout/manual call point), call 101/112, attempt first-aid firefighting only if trained and safe (PASS), evacuate via nearest exit, never use lifts, close doors, go to assembly point, head count by wardens, report missing persons to incident controller, nobody re-enters until all-clear.","Incident controller liaises with fire brigade; provide site plan, chemical inventory, isolation points.","After fire: preserve scene for investigation; report per OSH Code s.11 (dangerous occurrence) within 12 h; MSIHC major accident 48 h; insurance.","Review drill performance (evacuation time, head-count accuracy) and update plan.","Labour colonies: fire-resistant materials for huts, spacing, extinguishers, water drums, no electrical hazards, exits."],ppe:["ERT: fire-retardant suit, helmet, gloves, boots, SCBA for interior attack"],stop:["Exits blocked","Hydrant system out of service without compensatory measures","Fire detected – evacuate"],records:["Fire NOC, extinguisher register, hydrant/pump tests, alarm tests, drill records, warden training, fire incident reports"],refs:{india:["Factories Act s.38; IS 3844 & IS 13039 hydrants/hose reels; IS 2189 FDAS; IS 11457 Pt 1","NBC 2016 Part 4 (fire & life safety) & Part 7; IS 2190, IS 15683 (extinguishers); IS 13039 (hydrants), IS 15105 (sprinklers), IS 2189 (fire alarm); IS 3844 (high-rise)","Factories Act s.38 (fire precautions – via state rules); OSH Code s.6; BOCW Central Rules 1998 fire protection chapter","Petroleum Rules 2002; Gas Cylinders Rules 2016; MSIHC Rule 13 on-site emergency plan"],ka:["KA Factories Rule 66 (fire); KSFES Fire NOC","Karnataka Fire Force Act 1964; KSFES NOC conditions; Karnataka Factories Rules fire provisions; BBMP bye-laws"],tn:["TN Factories Rule 61-A (fire); TNFRS Fire NOC","TN Fire Service Act 1985; TNFRS fire licence/NOC; TN CDBR 2019; TN Factories Rules fire provisions"],osha:["1926 Subpart F (1926.150–155); 1910.38 EAP; 1910.39 FPP; 1910.157 extinguishers; 1910.164/165 alarms; NFPA 241, NFPA 10, NFPA 101, NFPA 1600"],intl:["UK Regulatory Reform (Fire Safety) Order 2005; HSG168 Fire safety in construction; ILO CoP Construction"]},checklist:"cl-fire"},

{id:"emergency",t:"Emergency Response & On-Site Emergency Plan",cat:"Fire & Emergency",tags:["Chemical","Industrial","Construction"],purpose:"Ensure a prepared, rehearsed response to fire, explosion, toxic release, structural collapse, medical emergency, flood/cyclone, earthquake, bomb threat, and civil disturbance; integrate with district off-site plans.",scope:"All sites; mandatory written on-site emergency plan for MAH units (MSIHC Rule 13) and hazardous-process factories; construction sites per BOCW rules (emergency action plan).",roles:["Site Main Controller (SMC) – overall command","Incident Controller (at scene)","Emergency Response Team leader; fire team; rescue team; first-aid team","Communications officer; security; liaison with police/fire/district authority","Mutual-aid partners"],hazards:["Delayed alarm; unclear command; unprepared responders become casualties","Loss of utilities; inaccessible roads; monsoon flooding/cyclone (TN coast); Karnataka/TN heat waves","Media/public panic; secondary incidents"],pre:["Written plan: hazard inventory, scenarios (worst credible), roles, alarm codes, assembly points (upwind alternatives), emergency control centre with phones/radios/drawings/SDS/wind sock, shelter-in-place rooms for toxic release","Emergency contacts board at gate and ECC: 112, 101, 108/102, nearest hospital(s) with burn/trauma capability, police, District Collector/ DEOC 1077, SPCB, Factory Inspector/ICF, utility helplines, poison centre","Equipment: fire systems, breathing apparatus, spill kits, gas detectors, stretchers, ambulance (own or tie-up within 15 min), first-aid room (≥ 500 workers), AEDs","Training: ERT quarterly; all staff induction; drills: fire 6-monthly, toxic release/chemical mock drill annual with District Crisis Group (MAH), evening/night-shift drill","Business continuity & crisis communication plan"],steps:["Detection & alarm: anyone can raise alarm; codes for fire/gas/evacuation/shelter-in-place; siren patterns displayed.","Activation: SMC declares level (1 = local, 2 = site, 3 = off-site); ECC activated; head counts at assembly points.","Response: ERT tackles incident within competence; isolate utilities (power, gas) as directed; account for contractors/visitors via gate register.","Medical: first-aiders stabilise; ambulance dispatch; hospital notified (nature – chemical burn, crush); casualty log.","Communication: single spokesperson; inform family of injured; notify authorities per statutory timelines (see Reporting view).","External: receive fire brigade/police at gate with site plan and chemical inventory; District Collector for off-site; inform neighbours if release.","Shelter-in-place for toxic gas: close doors/windows, stop AC, move to upper floors/designated rooms, monitor.","Natural hazard: cyclone/flood warning (IMD) – secure cranes (free slew), lower loads, stop WAH, move workers to safe shelters; heat wave – stop outdoor work at peak hours.","Stand-down only by SMC; scene preserved for investigation; debrief within 24 h.","Review plan annually and after every drill/incident; update contacts quarterly."],ppe:["ERT kit as per scenario (SCBA, chemical suits, fire kit)"],stop:["Responder without correct PPE","Unknown chemical involved","Structural instability"],records:["On-site emergency plan (approved by Chief Inspector for MAH), drill reports, ERT training, casualty logs, notification records, off-site plan correspondence"],refs:{india:["MSIHC Rules 13–15; Chemical Accidents (EPPR) Rules 1996; Disaster Management Act 2005 & NDMA chemical disaster guidelines","Factories Act s.41B(4) (emergency plan – via OSH Code Ch. XII); BOCW Central Rules 1998 emergency action plan; OSH Code s.6","NBC Part 4; IS 15656; IS 14489"],ka:["MAH Control (Karnataka) Rules 1994 (on/off-site plans)","KSDMA district plans; Karnataka Factories Rules on-site emergency plan approval (DFBISH); KSFES"],tn:["TN CIMAH Rules 1994 (off-site emergency inputs)","TNSDMA district plans (cyclone/flood – Chennai, coastal); DISH TN MAH drills; TNFRS"],osha:["1910.38 Emergency Action Plan; 1910.120(q) emergency response; 1910.119(n) emergency planning; 1926.35; NFPA 1600; NFPA 1620"],intl:["Seveso III Art. 12 emergency plans; ILO C174; ISO 22301; ISO 45001 cl. 8.2"]},checklist:"cl-emergency"},

{id:"incident",t:"Incident Reporting, Investigation & Statutory Notification",cat:"Management",tags:["Construction","Industrial","Chemical"],purpose:"Capture every injury, illness, dangerous occurrence, near miss and environmental release; meet statutory notification deadlines; find root causes and prevent recurrence.",scope:"All work-related incidents involving employees, contractors, visitors and the public; property damage; environmental releases; security events.",roles:["First responder/supervisor (immediate report)","Safety officer (classification, statutory notices)","Investigation team (lead trained in RCA; worker rep; engineer)","Site head (approval, resources)","HR/medical (compensation, ESI, records)"],hazards:["Late or missed statutory notice (penalties, loss of insurance)","Scene disturbed; evidence lost","Blame culture suppressing near-miss reporting"],pre:["Incident classification matrix (fatal, lost-time, restricted, medical treatment, first aid, near miss, dangerous occurrence, occupational disease, environmental, property)","Notification flowchart with deadlines by jurisdiction (see Reporting view); pre-filled Form XI / state accident forms; contacts of ICF, police, DM/SDO, Electrical Inspector, Boiler Inspector, SPCB, PESO, ESIC","RCA methodology (5-Why, fishbone, TapRooT, ICAM); investigation kit (camera, tape, cones, witness forms)","KPI definitions: LTIFR, TRIR, severity rate (IS 3786 / OSHA 1904 method)"],steps:["Make area safe; rescue and first aid; call 108/112; isolate hazard; prevent secondary incidents.","Report immediately to supervisor and safety officer (within 1 h internal); log in incident register with unique number.","Preserve scene (do not disturb until inspector permits for fatal/serious – legal requirement); photographs, measurements, witness names.","Statutory notification: death – forthwith to ICF (electronically + written), police and family (OSH Central Rules Rule 7; state rules); injury ≥ 48 h absence / dangerous occurrence – within 12 h in Form XI (central sphere) or per state rule (often 4–24 h); MSIHC major accident – 48 h (Schedule 6); electrical accident – 48 h to Electrical Inspector; boiler – 24 h; ESIC accident report – 24 h; Employee's Compensation Commissioner – fatal within 7 days; SPCB – environmental release forthwith/Form 11; PESO – forthwith; OSHA (US sites) – fatality 8 h, hospitalisation/amputation/eye loss 24 h.","Investigation within 24–72 h: sequence of events, immediate causes (unsafe acts/conditions), underlying causes (management system), root causes; use hierarchy of controls for actions.","Corrective & preventive actions with owner and due date; tracked to closure; verify effectiveness.","Communicate lessons (safety alert, toolbox talk); share with corporate/client.","Occupational disease: medical practitioner reports (OSH Code s.12 / Factories Act s.89 Third Schedule) to ICF; employer notice.","Maintain registers: accident register, dangerous-occurrence log, first-aid register, near-miss log; annual return.","Monthly KPI review at safety committee; trend analysis."],ppe:["As required for scene access"],stop:["Scene unsafe","Attempting to move fatal/serious casualty before medical advice (unless further danger)"],records:["Incident register, statutory notices with acknowledgements, investigation reports, CAPA tracker, medical records, annual return"],refs:{india:["OSH Code 2020 s.10–s.12; OSH (Central) Rules 2026 Rule 7 (Form XI; 12 h; death forthwith)","Factories Act s.88/88A/89 (legacy – state rules forms/timelines); BOCW rules accident notice","MSIHC Rule 5 (48 h, Sch. 6); CEA Safety Regs 2023 (48 h electrical); Boilers Act 2025 (24 h); EP Act s.9; HOWM Rule 23 (Form 11); Petroleum/Explosives Rules (forthwith)","Code on Social Security 2020 (Employee's Compensation – fatal report 7 days; ESI accident report); IS 3786 statistics"],ka:["Karnataka Factories Rules 1969 notice of accidents (Form 18 – verify, timelines); Karnataka BOCW Rules; DFBISH online accident portal"],tn:["TN Factories Rules 1950 notice of accidents (Form – verify); DISH TN online; TN BOCW Rules"],osha:["29 CFR 1904 (300/300A/301; 8 h/24 h reporting); 1926.20; OSHA Fatality/Catastrophe investigation procedures"],intl:["UK RIDDOR 2013; ISO 45001 cl. 10.2 incident, nonconformity; ILO Recording & notification of occupational accidents (C155 Art. 11, R194)"]},checklist:"cl-incident"},

{id:"hira",t:"Hazard Identification & Risk Assessment (HIRA) / Job Safety Analysis (JSA)",cat:"Management",tags:["Construction","Industrial","Chemical"],purpose:"Systematically identify hazards, evaluate risk and define controls before work, and keep assessments live as conditions change.",scope:"Baseline site/plant HIRA; activity-based JSA/method statements; task-specific dynamic risk assessment; process hazard analysis (HAZOP/What-if/LOPA) for process plants; environmental aspect-impact register.",roles:["Assessment lead (trained)","Workers who do the task","Supervisor","Engineer/process specialist","EHS reviewer/approver"],hazards:["Generic copy-paste assessments; controls not implemented; no review after change"],pre:["Risk matrix (likelihood × severity, e.g. 5×5) with acceptance criteria; legal register linked","Templates: HIRA register, JSA (steps-hazards-controls), method statement, PHA worksheets","Legal and standard requirements identified (OSH Code s.6; ISO 45001 cl. 6.1.2)"],steps:["Break the job into steps (observe or walk-through with the crew).","For each step list hazards: physical, chemical, biological, ergonomic, psychosocial, environmental, and energy sources (gravity, electricity, pressure, motion, chemical, thermal, radiation).","Rate risk (unmitigated) with matrix; identify who is harmed (workers, contractors, public).","Apply hierarchy of controls: eliminate → substitute → engineering → administrative (procedures, permits, training) → PPE.","Rate residual risk; if above acceptance, add controls or escalate; obtain approvals (high-risk = site head).","Convert into method statement/toolbox-talk content; communicate to crew in local language; crew signs.","Implement; supervisor verifies controls in place before start (pre-task briefing).","Review: on change of scope/equipment/people, after incident/near miss, at fixed interval (annually; monthly for high-risk sites), at monsoon start.","Process plants: HAZOP at design and every 5 years / on MoC; LOPA/SIL for safeguards; bow-tie for MAH scenarios.","Maintain risk register; feed into safety committee, objectives and training plan."],ppe:["Determined by assessment"],stop:["No assessment for new/high-risk task","Controls not available at site"],records:["HIRA register, JSAs/method statements, PHA reports & action close-out, legal register, review log"],refs:{india:["OSH Code 2020 s.6 (duties incl. risk assessment as prescribed); Factories Act s.7A/41B (via rules); IS 15656 HAZOP; IS 14489; BOCW site safety plan","MSIHC Rule 10 safety report (hazard analysis)"],ka:["Karnataka Factories (Safety Audit) Rules 2024 – audit expects documented HIRA"],tn:["DISH TN inspection checklist – HIRA/site safety plan; TN BOCW Rules"],osha:["1926.20(b) accident prevention programs; 1910.132(d) PPE hazard assessment; 1910.119(e) PHA; OSHA 3071 JHA guide; 1910.146(c) confined space evaluation"],intl:["ISO 45001 cl. 6.1.2 & 8.1.2; ISO 31000; ISO 12100; IEC 61882 HAZOP; UK MHSWR reg 3; HSE INDG163; CDM 2015 construction phase plan"]},checklist:"cl-daily"},

{id:"ppe",t:"Personal Protective Equipment Programme",cat:"Health",tags:["Construction","Industrial","Chemical"],purpose:"Select, issue, use, maintain and replace PPE correctly as the last line of defence after higher-order controls.",scope:"Head, eye/face, hearing, respiratory, hand, foot, body, fall protection and hi-vis PPE for employees, contractors and visitors.",roles:["Safety officer (PPE hazard assessment/matrix)","Stores (issue register)","Supervisors (enforcement)","Workers (use & care)"],hazards:["Wrong PPE for hazard (e.g. dust mask for solvent vapour), counterfeit/uncertified PPE, poor fit, non-use due to heat/discomfort"],pre:["Written PPE hazard assessment per area/task (OSHA 1910.132(d); OSH Code s.6)","Specification to standards: helmets IS 2925/EN 397 (ISI mark mandatory under QCO); safety footwear IS 15298 Pt 2/EN ISO 20345; goggles IS 5983/EN 166; hearing IS 9167/EN 352; respirators IS 9473/EN 149 (FFP2/3) & cartridges EN 14387; gloves IS 6994/EN 388/EN 374; harness IS 3521/EN 361; hi-vis IS 15809/ISO 20471; arc-rated per NFPA 70E/IEC 61482","Free issue to workers (employer cost – statutory), replacement schedule, sizes stocked","Fit testing for tight-fitting respirators; medical evaluation","Training on donning/doffing, limitations, inspection, storage"],steps:["Issue PPE on induction against signed register; record sizes and dates.","Mandatory minimum on site: helmet, safety boots, hi-vis; task PPE per matrix and permit.","Daily pre-use inspection by wearer; damaged PPE replaced immediately (no cost to worker).","Respirators: clean-shaven for tight-fit; cartridge change schedule; store sealed; disposable FFP replaced each shift.","Hearing: ear plugs/muffs where ≥ 85 dB(A); signage; audiometry for exposed workers annually.","Fall protection: 6-monthly competent inspection; retire after fall or per manufacturer life (typically 5 years from first use).","Heat: breathable FR/cotton, cooling vests, shaded rest; schedule heavy work out of peak heat.","Visitors: PPE at gate with escort.","Enforcement: supervisors stop non-compliant work; progressive discipline; recognise good practice.","Review matrix on new hazards, incidents, and PPE standard changes (e.g. new QCOs)."],ppe:["Programme defines all"],stop:["Working without mandatory PPE","Uncertified/counterfeit PPE in use"],records:["PPE hazard assessment, specifications, issue register, inspection records (harness), fit-test and audiometry records, training"],refs:{india:["BIS/ISI-certified PPE: helmets IS 2925; footwear IS 15298 Pts 2–4; eye IS 5983 & IS 8520; gloves IS 6994; electrical gloves IS 4770 & IS 13774; hearing IS 9167 & IS 6229; filtering half masks IS 9473; gas filters IS 15322; hi-vis IS 15809; heat & flame clothing IS 15748; showers/eyewash IS 10592; fall arrest IS 3521:2021 Pts 1–5","OSH Code 2020 s.6 (employer to provide PPE free); Factories Act s.35 (eye) via rules; BOCW Central Rules 1998 PPE rules (helmets, belts, footwear); KA/TN BOCW Rules","BIS: IS 2925, IS 15298, IS 5983, IS 9167, IS 9473, IS 3521, IS 6994, IS 15809; Quality Control Orders for helmets/footwear/eyewear","Karnataka/TN Factories Rules – PPE for dangerous operations"],ka:["KA Factories Rule 65 / Rule 88: PPE must carry BIS certification","Karnataka Factories Rules 1969 (PPE in scheduled operations); Karnataka BOCW Rules"],tn:["TN Factories Rule 61-O: PPE must carry BIS certification","TN Factories Rules 1950 (PPE in Sch. operations); TN BOCW Rules"],osha:["1910 Subpart I (1910.132–140); 1926 Subpart E (1926.95–106); 1910.134 respiratory; 1910.95 hearing; ANSI Z87.1, Z89.1, Z359; ASTM F2413"],intl:["UK PPE at Work Regs 1992 (amended 2022); EU PPE Regulation 2016/425; EN standards; ILO CoP Construction – PPE"]},checklist:"cl-ppe"},

{id:"contractor",t:"Contractor & Subcontractor Safety Management",cat:"Management",tags:["Construction","Industrial","Chemical"],purpose:"Ensure contractors work to the same standard as the principal employer; discharge principal-employer liability under OSH Code Ch. XI.",scope:"Pre-qualification, contract clauses, mobilisation, supervision, performance monitoring and close-out for all contractors (civil, mechanical, electrical, scaffolding, crane hire, labour supply, cleaning, security).",roles:["Contracts/procurement","Principal employer's safety officer","Contractor's safety officer/supervisor","Site head"],hazards:["Unlicensed contractors; untrained migrant workers; wage/welfare defaults attributed to principal employer","Interface hazards between contractors (SIMOPS)"],pre:["Pre-qualification: OSH Code contractor licence (50+ workers), safety statistics (LTIFR), ISO 45001/competence, insurance (EC/WC policy, PLI), past prosecutions","Contract HSE clauses: site rules, PTW, PPE, penalties/incentives, reporting, right to stop work, safety officer requirement by headcount, medical fitness, age proof (no child/adolescent in hazardous work)","Mobilisation checklist: worker registration (BOCW board, ESI/EPF), induction, medical, tool/equipment inspection, lifting gear certificates, electrician licences","Interface/SIMOPS matrix and coordination meetings"],steps:["Issue site HSE plan and rules with contract; kick-off HSE meeting before mobilisation.","Verify licences, registrations (contract labour licence, BOCW), insurance, competence certificates; approve contractor's method statements and HIRA.","Induct every worker (ID card with photo, blood group, emergency contact, induction date); maintain gate register; daily toolbox talks by contractor supervisors.","Joint weekly inspections; score cards (leading indicators: toolbox talks, inspections, near-miss reports; lagging: injuries).","Enforce PTW and stop-work authority; non-conformance notices; escalating sanctions.","Welfare: verify wages paid, PF/ESI, drinking water, latrines, rest sheds, crèche, canteen, accommodation standards (labour camps) — principal employer liable on default.","Inter-state migrant workers: journey allowance, helpline, portability; language-appropriate training.","Incident reporting by contractor within 1 h; principal employer files statutory notices where it is the 'employer' under the Code.","Monthly HSE performance review; quarterly audit; demobilisation close-out (clearance only after safe removal of equipment, waste, scaffolds).","Keep records for statutory period."],ppe:["Per site matrix"],stop:["Contractor without valid licence/insurance","Unregistered/under-age worker","Repeated serious non-conformance"],records:["Pre-qualification files, licences, contractor HSE plans, induction registers, inspection scorecards, NCRs, performance reviews"],refs:{india:["OSH Code 2020 Ch. XI contract labour (licence, principal employer duties, welfare), Ch. XIII BOCW; Code on Social Security (ESI, EPF, cess, EC)","Child & Adolescent Labour Act 1986; Inter-state migrant provisions (OSH Code Ch. XI Part II)"],ka:["Karnataka BOCW Rules 2006; Karnataka OSH draft rules 2026; Karnataka labour camp standards (Labour Dept)"],tn:["TN BOCW Rules 2006; TN contract labour rules (now OSH); DISH TN"],osha:["OSHA Multi-Employer Citation Policy (CPL 02-00-124): creating/exposing/correcting/controlling employers; 1910.119(h) PSM contractors; 1926.16"],intl:["CDM 2015 (principal contractor/contractor duties); ISO 45001 cl. 8.1.4.2 contractors; ILO CoP Construction – coordination"]},checklist:"cl-contractor"},

{id:"training",t:"Safety Induction, Training, Competence & Toolbox Talks",cat:"Management",tags:["Construction","Industrial","Chemical"],purpose:"Ensure every person has the knowledge and competence for their task and hazards, in a language they understand.",scope:"Site induction (all persons), job-specific training, statutory certifications (competent persons, operators, electricians, first-aiders, fire wardens, scaffolders, riggers), refresher, toolbox talks, visitor briefings.",roles:["Safety officer/training coordinator","Supervisors (toolbox talks)","External accredited trainers (NSC, CLI/DGFASLI, OEMs)"],hazards:["New workers (first 30 days) have highest injury rates; language barriers (Kannada/Tamil/Hindi/Odia/Bengali migrant mix)"],pre:["Training needs matrix by role; statutory list (e.g. crane operator licence, scaffold inspector, electrical supervisor licence, first-aid certificate from St John/approved centre, fire warden, confined-space, radiography RSO)","Induction content: site hazards, rules, PTW, PPE, emergency, reporting, welfare, rights (no retaliation), POSH; audio-visual in local languages; test","Training records with validity; ID card colour/sticker shows induction & skills"],steps:["Induct before first entry (2–4 h); issue ID; buddy for first week; mark 'new worker' helmet sticker for 30 days.","Job-specific training with practical assessment (e.g. harness donning, extinguisher use, gas detector).","Statutory refreshers: induction annually; WAH/confined/LOTO every 2 years or on change; first aid 3-yearly; operators per licence.","Daily toolbox talk (10–15 min) by supervisor on the day's tasks and permit conditions; attendance signed; topic library (see Toolbox Talks view).","Mock drills count as training; record participation.","Supervisor/line-manager training: legal duties, incident investigation, behaviour-based safety.","Evaluate effectiveness: observations, audit findings, quiz scores; retrain where gaps.","Keep training records ≥ 3 years (longer for statutory certificates)."],ppe:["N/A"],stop:["Untrained person on high-risk task","No induction"],records:["Training matrix, attendance, certificates, toolbox talk sheets, competence assessments"],refs:{india:["OSH Code 2020 s.6 (information, instruction, training, supervision); Factories Act s.41C/111A (via rules); BOCW Rules (training, safety officer duties)","State Factories Rules safety officer/first-aid training providers (TN Rule 63-B)"],ka:["Karnataka Factories Rules 1969; Karnataka BOCW Rules; DFBISH training circulars"],tn:["TN Factories Rules 1950 (Rule 63-B first-aid training); DISH TN"],osha:["1926.21 safety training; 1910.132(f); 1910.147(c)(7); 1926.503; 1926.1207; OSHA 10/30-hour outreach; ANSI Z490.1"],intl:["ISO 45001 cl. 7.2/7.3; CDM 2015 reg 15; ILO C155 Art. 19; CSCS/IOSH/NEBOSH schemes"]},checklist:"cl-training"},

{id:"manual",t:"Manual Handling & Ergonomics",cat:"Health",tags:["Construction","Industrial"],purpose:"Prevent musculoskeletal injuries from lifting, carrying, pushing, pulling and repetitive or awkward work.",scope:"Cement bags (50 kg), rebar, blocks, pipes, drums, formwork panels, equipment; repetitive bar bending, tiling, plastering, overhead work; workstation ergonomics.",roles:["Supervisors","Workers","Safety/occupational health"],hazards:["Loads > guideline weights; twisting; above-shoulder/below-knee lifts; long carries; team lifts uncoordinated; heat compounding fatigue"],pre:["Mechanical aids: trolleys, pallet trucks, hoists, vacuum lifters, conveyors; design-out (25 kg cement bags, pre-cut rebar)","Statutory maximum weights (state Factories Rules, Rule on 'maximum permissible loads' — commonly adult male 50 kg, adult female 30 kg, adolescent 30/20, child not permitted — verify; good practice ≤ 25 kg single-person lift, NIOSH 23 kg)","TILE assessment (Task, Individual, Load, Environment); ISO 11228"],steps:["Avoid: deliver materials close to point of use; use plant; reduce load size.","Assess remaining manual tasks (TILE/NIOSH equation); set team-lift rules (2 persons for 25–50 kg).","Train lifting technique: plan route, stable base, bend knees, keep load close, no twisting, smooth movement; team lifts with one leader.","Rotate repetitive tasks; micro-breaks; adjustable workstations for bar bending/pipe fitting.","Provide gloves with grip, shoulder pads, and handles/hooks for blocks and rebar.","Heat: more rest in hot hours; hydration (see heat stress).","Early reporting of pain; medical review; modified duties.","Review incidents and MSD symptoms at safety committee."],ppe:["Gloves, safety boots, shoulder pads, back support only where prescribed"],stop:["Single-person lift beyond limit","Unsafe route/footing"],records:["Manual handling assessments, training, MSD reports"],refs:{india:["Factories Act s.34 maximum loads (via state rules); OSH Code s.6; BOCW Rules (materials handling)","IS 7969 handling/storage of building materials; IS 7293 cement"],ka:["Karnataka Factories Rules 1969 (maximum loads – verify figures)"],tn:["TN Factories Rules 1950 (maximum loads – verify figures)"],osha:["General Duty Clause; 1926.250 materials handling; NIOSH Lifting Equation; OSHA ergonomics guidelines"],intl:["UK Manual Handling Operations Regs 1992; HSE MAC tool; ISO 11228-1/2/3; EU Directive 90/269/EEC"]},checklist:"cl-daily"},

{id:"heat",t:"Heat Stress Management (Outdoor & Hot-Process Work)",cat:"Health",tags:["Construction","Industrial"],purpose:"Prevent heat exhaustion, heat stroke and heat-related accidents in Karnataka/Tamil Nadu summers (Mar–Jun; Chennai humid heat) and hot processes (foundries, boilers, kilns, bitumen).",scope:"All outdoor work, roof/ height work, confined spaces, hot plants; new and returning workers; PPE-heavy tasks (FR suits, respirators).",roles:["Site head (work scheduling)","Supervisors (monitoring, rest breaks)","First-aiders","Safety officer (WBGT/heat index monitoring)"],hazards:["Heat stroke (core > 40 °C; confusion; can be fatal), heat exhaustion, cramps, syncope, dehydration-related falls and errors","Risk amplified by humidity, no acclimatisation, illness, medication, impermeable PPE"],pre:["Heat illness prevention plan triggered by IMD heat-wave alerts / State Heat Action Plan; WBGT monitor or heat-index chart; ACGIH TLV WBGT action limits by workload","Water: ≥ 1 cup (250 ml) every 15–20 min; cool potable water within 100 m; ORS available; shaded rest areas with fans/misting; cooling vests for FR work","Acclimatisation: new/returning workers 20% workload day 1, +20%/day over 5–7 days (OSHA NEP focus)","Buddy system; emergency plan for heat stroke (cool first – ice water immersion/cold wet sheets – then transport)"],steps:["Check forecast daily; post heat level (green/amber/red) at gate.","Schedule heavy work early morning/evening; red level: no heavy outdoor work 12–3 pm (or per state advisory); shift adjustments.","Work/rest cycles per WBGT and workload (e.g. heavy work at WBGT 30 °C: 25% work/75% rest for unacclimatised).","Supervisors observe for symptoms (headache, dizziness, cramps, confusion, cessation of sweating); never leave symptomatic worker alone.","Encourage drinking before thirst; avoid caffeinated/sugary drinks; monitor urine colour chart in toilets.","Clothing: light, loose, cotton; helmet with brim/neck flap; sunscreen.","Confined/hot spaces: ventilation, shorter rotations, physiological monitoring where WBGT > TLV.","Heat stroke response: call 108, move to shade, remove excess clothing, aggressive cooling (immerse/douse with cold water, fan), do not give fluids if unconscious.","Record heat illness as incident; review schedule.","Training in local language before summer each year."],ppe:["Light cotton clothing, helmet neck flap, cooling vest, sunglasses (where no eye hazard conflict)"],stop:["Worker shows confusion/collapse","WBGT above ceiling for workload with no engineering control","No water/shade available"],records:["WBGT/heat-index log, acclimatisation schedules, heat illness incidents, training"],refs:{india:["OSH Code s.6 & s.24 (drinking water, rest facilities); Factories Act s.13/18 (temperature, drinking water – via rules); BOCW Rules (drinking water, rest shelters)","NDMA Heat Wave Guidelines; Karnataka & Tamil Nadu State Heat Action Plans; IMD alerts","IS 3646 (lighting/ventilation), ACGIH TLV adopted in Indian practice"],ka:["Karnataka Heat Action Plan (KSDMA); Labour Dept summer advisories (timing of outdoor work)"],tn:["Tamil Nadu Heat Action Plan (TNSDMA); Labour Welfare Dept advisories; Chennai Corporation heat advisories"],osha:["General Duty Clause §5(a)(1); OSHA Heat NEP CPL 03-00-024 (Apr 2026); proposed 29 CFR 1910.148; NIOSH Criteria for Heat Stress 2016; state heat rules (CA T8 §3395 etc.)"],intl:["ISO 7243 (WBGT), ISO 7933 (PHS); ILO heat guidance; ACGIH TLVs"]},checklist:"cl-heat"},

{id:"noise",t:"Noise & Vibration Control",cat:"Health",tags:["Construction","Industrial"],purpose:"Prevent noise-induced hearing loss and hand-arm/whole-body vibration syndrome; comply with ambient noise limits for neighbours.",scope:"Breakers, compressors, DG sets, piling, grinders, cutting, concrete pumps, compaction plant, process plant (compressors, mills), vehicles.",roles:["Safety officer (surveys)","Occupational health (audiometry)","Supervisors"],hazards:["Occupational exposure ≥ 85 dB(A) 8-h TWA; impulse noise; HAV from breakers/grinders; WBV from plant seats","Community complaints; night-work restrictions"],pre:["Noise survey (sound level meter, dosimetry) and HAV exposure estimates (manufacturer vibration data, trigger times)","Hearing conservation programme where ≥ 85 dB(A): audiometry baseline & annual, hearing protection, training","Ambient limits: industrial area 75/70 dB(A) day/night at boundary; no night construction noise without permission (Noise Rules 2000); DG sets with acoustic enclosures"],steps:["Eliminate/substitute: hydraulic breakers with silenced tips, electric over diesel, rubber lining chutes.","Engineering: enclosures, screens, silencers, anti-vibration mounts; maintain equipment (worn bearings raise noise).","Zoning: mark hearing-protection zones ≥ 85 dB(A) with signs.","Admin: rotate workers; limit HAV trigger time (EAV 2.5 m/s² A(8), ELV 5 m/s²); job rotation; warm hands/gloves.","PPE: plugs/muffs rated for level (SNR), fit-trained; double protection > 105 dB(A).","Monitor boundary noise near residences/schools/hospitals; adjust timing (no piling at night).","Audiometry annually for exposed workers; refer standard threshold shifts.","Record exposures; review when plant changes."],ppe:["Ear plugs/muffs (IS 9167/EN 352), anti-vibration gloves (limited benefit)"],stop:["Exposure > 90 dB(A) without protection","Complaint of tingling/numbness from vibrating tools"],records:["Noise survey, dosimetry, audiometry, HAV exposure log, community monitoring"],refs:{india:["IS 7194 assessment of noise exposure; workroom 8-h TWA 85–90 dB(A); ambient industrial 75/70 dB(A)","Factories Act Sch. II noise 90 dB(A) (via state rules; OSH Code exposure limits); Noise Pollution Rules 2000; EP Rules Sch. VI (DG sets, construction equipment limits)","Noise-induced hearing loss is a notifiable disease (Third Schedule); BOCW Central Rules 1998 (noise & vibration chapter)"],ka:["KSPCB construction noise; Karnataka Factories Rules (noise schedule – verify)"],tn:["TNPCB; TN Factories Rules (noise – verify)"],osha:["1910.95 (85 dB(A) action level; 90 PEL); 1926.52/.101; NIOSH REL 85 dB(A) 3 dB exchange"],intl:["UK Noise at Work Regs 2005; Control of Vibration at Work Regs 2005; ISO 9612; ISO 5349; EU 2002/44/EC, 2003/10/EC"]},checklist:"cl-daily"},

{id:"respiratory",t:"Respiratory Protection, Dust, Silica & Asbestos",cat:"Health",tags:["Construction","Industrial","Chemical"],purpose:"Prevent silicosis, asbestosis, COPD, lung cancer and acute poisoning from airborne contaminants.",scope:"Concrete/stone cutting and grinding, drilling, sandblasting (prohibited in many rules – use wet/grit alternatives), demolition, cement handling, welding fumes, paint spraying, insulation, asbestos-cement work, solvents, confined spaces.",roles:["Safety officer (exposure assessment)","Occupational physician (medical surveillance)","Supervisors","Workers"],hazards:["Respirable crystalline silica (RCS) – PEL 0.05 mg/m³ (OSHA; India Sch. II lower?), asbestos (0.1 f/cc OSHA), cement dust, wood dust, welding fumes (Mn, Cr VI), isocyanates, solvents; O2 deficiency; CO from engines"],pre:["Exposure assessment; control plan per task (OSHA Table 1 style: wet cutting, LEV with HEPA, enclosed cabs)","Respiratory protection programme: selection by assigned protection factor, fit test (qualitative/quantitative) annually, medical evaluation, cleaning, cartridge change-out, training","Medical surveillance: chest X-ray (ILO classification), spirometry for silica/asbestos-exposed (state rules dangerous-operations schedules); records retained long-term"],steps:["Eliminate: pre-cast, prefabricated, non-silica abrasives; prohibit dry sweeping — use vacuum/wet.","Engineering: water suppression on saws/drills, LEV with HEPA on grinders, enclosed cabs with filtered air, downdraft tables, ventilation.","Admin: restricted zones, rotation, signage, hygiene (no eating in dusty areas, laundering of contaminated clothing on site — not taken home).","PPE: FFP2 (N95) minimum for nuisance/cement dust; FFP3/P100 or half-mask P3 for silica/asbestos; PAPR/airline for high exposures; organic-vapour cartridges for solvents; SCBA for IDLH/unknown.","Asbestos: survey before work; only licensed agency for friable; AC sheets removed whole, wetted, no power tools; waste double-bagged to TSDF; air monitoring; medical surveillance per TN Factories Rules Sch. XX / KA rules.","Welding: LEV at arc; low-fume consumables; respirator for stainless/galvanised.","Monitor: personal sampling for silica/asbestos per plan; compare with PEL/TLV.","Medical: baseline and periodic; refer abnormal findings; report notifiable diseases (silicosis, asbestosis, byssinosis) under OSH Code s.12.","Record keeping for exposure and medical (≥ 30–40 years for carcinogens – verify)."],ppe:["Respirators per programme; eye protection; coveralls (disposable for asbestos)"],stop:["Dry cutting of concrete/stone without control","Suspected asbestos disturbed","Respirator not fit-tested for silica/asbestos work"],records:["Exposure assessments, sampling, fit tests, medical surveillance, asbestos survey/removal, training"],refs:{india:["Factories Act Sch. II PELs & Third Schedule diseases (via OSH Code Ch. XII rules); state Factories Rules dangerous operations (silica, asbestos, cement)","TN Factories Rules Sch. XX asbestos (2025 amendment); Karnataka Factories Rules asbestos/silica schedules","Hazardous & Other Wastes Rules 2016 (asbestos waste); BOCW Rules (dust)"],ka:["Karnataka Factories Rules 1969 (Rule 129 schedules)"],tn:["TN Factories Rules 1950 Rule 95 & Sch. XX"],osha:["1910.134 respiratory protection; 1926.1153 & 1910.1053 silica (Table 1, 50 µg/m³); 1926.1101/1910.1001 asbestos; 1926.55/1910.1000; 1926.57 ventilation"],intl:["UK COSHH 2002, Control of Asbestos Regs 2012; HSE INDG455; EN 149; ILO C162; IARC classifications"]},checklist:"cl-chemical"},

{id:"machine",t:"Machine Guarding & Safe Use of Plant/Power Tools",cat:"Industrial",tags:["Industrial","Construction"],purpose:"Prevent entanglement, crushing, shearing, cutting and ejection injuries from machinery and tools.",scope:"Bar-bending/cutting machines, concrete mixers, batching plants, compressors, conveyors, presses, lathes, grinders, saws, woodworking, pumps, drive belts; portable tools (angle grinders, drills, nail guns).",roles:["Maintenance engineer","Operators (trained/authorised)","Safety officer"],hazards:["Unguarded nip points/belts; missing emergency stops; bypassed interlocks; grinder disc burst (wrong RPM/size), kickback; loose clothing"],pre:["Machinery risk assessment (ISO 12100); guards (fixed, interlocked, adjustable), light curtains, two-hand controls per IS 9474/ISO 14120","Emergency stops accessible; isolation switches; pre-start alarm for conveyors","Operator authorisation; young persons (< 18) barred from dangerous machines (Factories Act s.23 / OSH Code)","Tool register with inspection colour-code (quarterly)"],steps:["Inspect guards daily; never operate with guards removed; report defects; tag out defective machines.","Grinders: disc RPM ≥ tool RPM, correct size, guard fitted, side handle, face shield + goggles, no cutting with grinding disc; 9-inch grinders restricted to trained users.","Mixers/batching plants: isolate before cleaning drum; interlocked hopper; no entry under raised skip.","Bar bending/cutting: foot pedal guard, no loose rebar ends, keep hands clear, ear/eye protection.","Conveyors: pull-cord stops, guards at nip points, no crossing except bridges, lockout for un-jamming.","Compressed air: never for cleaning clothing; whip checks on hose couplings; pressure relief.","Nail guns/powder-actuated tools: licensed operators, sequential trigger, exclusion zone, PPE.","Maintenance under LOTO; test guards after maintenance before release.","Keep machines in register with inspection dates; competent-person examinations per rules (e.g. pressure vessels, lifting)."],ppe:["Eye/face protection, gloves (not near rotating parts), hearing protection, no loose clothing/jewellery, hair tied"],stop:["Guard missing/bypassed","E-stop not working","Wrong abrasive disc"],records:["Machine register, guard inspection, tool inspection colour-code log, operator authorisation"],refs:{india:["Factories Act Ch. IV ss.21–31 (fencing, machinery in motion, young persons, hoists, lifting machines, revolving machinery, pressure plant); IS 16819 (safety of machinery design); IS 1991 Pts 1–10 (abrasive wheels)","Factories Act s.21–s.33 (fencing, machinery in motion, young persons, self-acting machines, casing) – via OSH Code s.6 and state rules","IS 9474 guarding of machinery; IS 1991; BOCW Central Rules (fencing of motors, hoists)"],ka:["KA Rule 56 Schedules I–VII (power presses, woodworking, rubber/plastic mills, centrifugals)","Karnataka Factories Rules 1969 (fencing, maintenance of machinery)"],tn:["TN Rule 53 Schedules I–VIII (textile machinery, cotton openers, woodworking, rubber mills, power presses, shears, guillotines)","TN Factories Rules 1950 (fencing, machinery)"],osha:["1910.212 machine guarding; 1910.219 mechanical power transmission; 1926.300–307 tools; 1926.302 power-operated hand tools"],intl:["UK PUWER 1998; ISO 12100; ISO 14120 guards; ISO 13849; EU Machinery Regulation 2023/1230"]},checklist:"cl-daily"},

{id:"cylinders",t:"Compressed Gas Cylinders – Storage, Handling & Use",cat:"Chemical",tags:["Construction","Industrial"],purpose:"Prevent cylinder explosions, fires, oxygen enrichment, asphyxiation and crushing injuries.",scope:"Oxygen, acetylene, LPG, argon, CO2, nitrogen, hydrogen, chlorine cylinders at sites and plants; manifolds; cryogenic dewars.",roles:["Stores in-charge","Users (welders, fitters)","Safety officer"],hazards:["Acetylene decomposition/flashback; oxygen with oil/grease; LPG leaks (heavier than air); valve shear on falling cylinder (projectile); inert gas asphyxiation in enclosed spaces"],pre:["Store outdoors/ventilated cage, shaded, on level ground, upright, chained, caps on; full/empty segregated; oxidisers ≥ 6 m or 1.5 m fire wall (30 min) from fuel gases; no sources of ignition within 3 m","PESO licence if quantities exceed thresholds; supplier test dates (hydro test within validity — 5/10 yrs by gas)","Colour coding per IS 4379; leak detection (soap solution); flashback arrestors; regulators matched to gas"],steps:["Receive: check test date, valve, cap, leaks; reject damaged; record.","Transport on cylinder trolley, secured upright; never roll on side, drag, lift by cap/valve, or use crane slings (use cage).","Use: open valve slowly standing to side; acetylene valve ≤ 1.5 turns, key left in place; regulator pressures (acetylene ≤ 1 bar); flashback arrestors both ends; hoses colour-coded, clamped, free of oil.","LPG: never in basements/pits/confined spaces; detect leaks with soap; hoses BIS-marked, replaced 2-yearly; regulators with pressure relief.","Inert gases: ventilation/oxygen monitoring in enclosed areas (purging, argon welding in tanks).","Close valves when not in use and at end of shift; remove regulators for transport; return empties marked 'MT'.","Fire involving cylinder: evacuate 100+ m, cool with water from behind cover, call fire service; acetylene cylinder that has been heated must be cooled 24 h (fire service).","Monthly storage inspection; quarterly hose/regulator inspection."],ppe:["Gloves, eye protection, safety boots; face shield for connecting"],stop:["Cylinder without cap/chain","Leak detected","Oil/grease on oxygen fittings","Past test date"],records:["Cylinder register, PESO licence, inspection logs"],refs:{india:["IS 11006 flashback arrestors","Gas Cylinders Rules 2016 (PESO); SMPV(U) Rules 2016; IS 4379; IS 818; IS 3016; Petroleum Rules (LPG per LPG rules)","Factories Act s.37 (explosive/inflammable gas) via rules"],ka:["PESO Sub-circle Mangaluru/Bengaluru","Karnataka Factories Rules; KSFES"],tn:["PESO Southern Circle Chennai","TN Factories Rules; TNFRS"],osha:["1926.350 gas welding and cutting; 1910.101 compressed gases; 1910.253; CGA pamphlets P-1; NFPA 55"],intl:["UK BCGA codes of practice; EIGA documents; ISO 10156"]},checklist:"cl-hotwork"},

{id:"traffic",t:"Site Traffic, Mobile Plant & Pedestrian Segregation",cat:"Construction",tags:["Construction","Industrial"],purpose:"Prevent persons being struck or run over by vehicles and plant (leading cause of construction fatalities with falls and electrocution).",scope:"Tippers, transit mixers, excavators, loaders, forklifts, cranes, hydras, rollers, dumpers, site cars; public road interface; loading/unloading; reversing.",roles:["Traffic marshal/banksman","Plant operators (licensed, competent)","Site logistics coordinator","Security (gate)"],hazards:["Reversing without banksman/alarm; blind spots; speeding; pedestrians in haul routes; unsecured loads; overturn on slopes/edges; refuelling fires"],pre:["Traffic management plan: one-way routes, speed limits (10–20 km/h), segregated pedestrian walkways with barriers, crossing points, parking, turning areas, lighting","Vehicle/plant: registration, fitness, insurance, reversing alarm/camera, beacon, seatbelt, ROPS/FOPS, mirrors; daily pre-start check; defect register","Operators: valid licence (HMV/CEV), site authorisation, medical fitness, no phone use; banksman trained","Public road: IRC:SP:55 signage, flagmen, wheel wash, no mud on road, covered loads"],steps:["Induct drivers/operators to the traffic plan; display plan at gate.","Keep pedestrians out of plant zones; where interaction unavoidable, banksman controls with radio; stop plant when pedestrian within swing/travel zone.","Reversing minimised (drive-through, turning circles); banksman always for reversing in congested areas; stand clear of path.","Loads secured/covered; height limits at overhead lines (goal posts); tippers: never travel with body raised; check overhead before tipping; stable level ground for tipping; stop blocks at edges.","Slopes/edges: plant kept away ≥ 1 m per 1 m depth from excavation edges; no operation across steep slopes.","Refuelling: engine off, no smoking, spill kit, bunded area; fuel bowser licensed.","Night: lighting, hi-vis class 3, reflective barriers.","Vehicle/plant inspection daily; maintenance records; tyre/brake checks.","Report near misses; review plan on layout change."],ppe:["Hi-vis (class 2/3), helmet, boots; seatbelt in plant"],stop:["No banksman for reversing in congested area","Pedestrian in exclusion zone","Alarm/camera not working","Tipping near edge without stop block"],records:["Traffic management plan, operator licences/authorisations, vehicle inspection logs, incident reports"],refs:{india:["Motor Vehicles Act 1988 & CMV Rules (CEV registration, licences); IRC:SP:55; BOCW Rules (transport, vehicles)","OSH Code s.6; Factories Act via rules (internal transport)"],ka:["Karnataka RTO; BBMP road cutting/ traffic police permits"],tn:["TN RTO; Chennai traffic police permits; TN CDBR site conditions"],osha:["1926.600–602 motor vehicles & mechanised equipment; 1926.601 (reverse alarms); 1910.178 PIT; 1926.1400 cranes"],intl:["UK HSG144 Safe use of vehicles on construction sites; Workplace (Health, Safety & Welfare) Regs 1992 reg 17; ILO CoP Construction"]},checklist:"cl-daily"},

{id:"concrete",t:"Concrete, Formwork & Falsework (Temporary Works)",cat:"Construction",tags:["Construction"],purpose:"Prevent formwork/falsework collapse, falls, concrete burns and pump/boom incidents.",scope:"Slab/column/wall formwork, shoring towers, props, scaffold-based falsework, slipform, precast erection, concrete pumping, rebar work.",roles:["Temporary works designer/coordinator","Site engineer","Formwork supervisor","Concrete pump operator; banksman"],hazards:["Collapse during pouring (overload, premature striking, inadequate bracing/foundation); boom contact with lines; hose whip; impalement on rebar; cement dermatitis/burns; falls from deck edges"],pre:["Temporary works design (loads, bracing, foundations) and checked drawings (BS 5975 TWC model); shoring tower load tables; props at correct extension","Formwork inspection and sign-off before pour (permit to pour); striking times per IS 456 (e.g. vertical forms 16–24 h; slab props 7–14 days depending on span) or cube results","Rebar caps/covers on protruding bars; edge protection on decks; access stairs/ladders","Pump: inspection certificate, outriggers, line clearance, hose restraints; washout area"],steps:["Install falsework per drawing on firm bearing (sole plates); plumb and brace; check prop pins/extensions.","Pre-pour inspection by engineer: supports, ties, bracing, cleanliness; issue pour permit.","Pour sequence controlled to avoid overloading; monitor for movement; stop pour if deflection/sound of distress.","Concrete pump: operator competent; boom clear of lines; nobody under boom; hose end held by two with restraint; pressure release before uncoupling; no hands near hopper agitator (interlock).","Skin protection: cement is alkaline — gloves, long sleeves, boots; wash splashes immediately; eye wash available.","Strike only on engineer's approval after required strength; re-prop as designed; never remove props prematurely for reuse.","Precast: lifting points designed; temporary propping until connections complete; exclusion zone.","Deck edges: guardrails before rebar fixing; openings covered; rebar caps.","Housekeeping: tie wire offcuts, nails in timber removed; slip/trip prevention; night lighting for pours.","Monsoon: drainage of formwork, ground softening checks for falsework foundations."],ppe:["Helmet, boots, gloves (nitrile/latex-coated), eye protection, harness at edges"],stop:["Movement of formwork during pour","Props on soft/unprepared ground","Boom within line clearance","Striking without approval"],records:["Temporary works design & check certificate, pour permits, striking approvals, pump inspection"],refs:{india:["IS 8989 safety code for erection of concrete-framed structures (formwork & centering); SP 70","IS 14687 Falsework for concrete structures – guidelines; IS 456; IS 3696; BOCW Central Rules 1998 (concrete work, formwork); NBC Part 7","KA/TN BOCW Rules"],ka:["BOCW (Karnataka Amendment) Rules 2024","Karnataka BOCW Rules 2006"],tn:["TN BOCW Rules 2006 (concrete formwork)","TN BOCW Rules 2006"],osha:["1926 Subpart Q (1926.700–706): formwork, shoring, reinforcing steel, precast, lift-slab; 1926.702 equipment (pumps)"],intl:["BS 5975 Code of practice for temporary works; EN 12812 falsework; UK HSE Temporary Works guidance"]},checklist:"cl-daily"},

{id:"steel",t:"Structural Steel Erection & Pre-Engineered Buildings",cat:"Construction",tags:["Construction","Industrial"],purpose:"Prevent falls, structural collapse during erection, dropped members and crane incidents.",scope:"Columns, beams, trusses, purlins, roof sheeting, PEB panels, bolting/welding at height, decking.",roles:["Erection engineer (sequence, stability)","Erection supervisor","Riggers, ironworkers (trained)","Crane team"],hazards:["Member falling before bolted (minimum 2 bolts rule); collapse without temporary bracing; walking on unsecured purlins/sheeting; fragile roof lights; wind"],pre:["Erection method statement with stability sequence and temporary bracing/guying; anchor bolts verified before column erection","Fall protection: lifelines/beam anchors designed; safety nets below steel; MEWPs for connections","Lifting plan; tag lines; pre-slung bundles (no loose purlins); weather limits"],steps:["Install anchor bolts and verify grout/levelling; columns erected with minimum 4 anchor bolts (OSHA) and temporary guys.","Beams landed and secured with at least two bolts wrench-tight at each connection before release from crane.","Connectors tie off 100% (SRL to beam anchor); use MEWP/scaffold where feasible; no 'beam walking' without lifeline.","Temporary bracing installed progressively; no bay left unbraced at end of day; check stability for wind.","Purlins/sheeting: install from secure platform/netting; crawl boards; roof-edge protection; no stepping on sheeting between purlins or on roof lights.","Dropped-object control: tool lanyards, exclusion zone below, no stacking loose bolts on beams.","Bolting: torque per design; welding at height with fire blankets below.","Decking: perimeter protection, controlled decking zone, cover openings immediately.","Stop at wind > 40 km/h (sheeting), lightning, poor visibility."],ppe:["Harness + SRL, helmet with chin strap, gloves, boots, eye protection"],stop:["Member not bolted before release","Missing bracing","High wind"],records:["Erection method statement, bracing sign-offs, lifting plans, net inspection"],refs:{india:["SP 70; IS 13416","IS 7205 Safety code for erection of structural steelwork; IS 800; BOCW Central Rules (structural frame erection); KA/TN BOCW Rules"],ka:["BOCW (Karnataka Amendment) Rules 2024","Karnataka BOCW Rules 2006"],tn:["TN BOCW Rules 2006 (structural steel erection)","TN BOCW Rules 2006"],osha:["1926 Subpart R (1926.750–761): site layout, hoisting, structural stability, column anchorage (4 bolts), beams & columns, open web joists, decking, fall protection (15 ft/30 ft rules), training"],intl:["BCSA/SCI guidance (UK); ILO CoP Construction – structural frames"]},checklist:"cl-wah"},

{id:"housekeeping",t:"Housekeeping, Waste Management & Environmental Controls",cat:"Management",tags:["Construction","Industrial","Chemical"],purpose:"Prevent slips/trips/falls, fire, pollution and penalties; comply with waste rules and consent conditions.",scope:"General housekeeping, material storage, C&D waste, hazardous waste, e-waste, batteries, plastic, bio-medical (first-aid room), used oil; dust, noise, water, dewatering discharge; labour camp sanitation.",roles:["Site admin/housekeeping in-charge","EHS officer","Stores","Waste contractors (authorised)"],hazards:["Trips on debris/cables; falling stacked materials; fire from waste; vector-borne disease in camps; SPCB directions/closure"],pre:["Waste management plan: segregation points (concrete/soil/steel/wood/plastic/hazardous), authorised vendors (SPCB-registered), manifests; C&D plan for ≥ 20,000 m² (2025 Rules)","CTE/CTO conditions understood (dust, noise, STP, DG); HW authorisation; e-waste/battery producer/bulk-consumer obligations","Dust control: barricade ≥ 3 m sheet, sprinkling, wheel wash, covered trucks, no burning","Camp: potable water testing, toilets (1 per 20), bathing, drainage, waste bins, fogging"],steps:["Daily clean-as-you-go; designated laydown areas; stacks ≤ 1.5 m (manual) with stable bases; walkways ≥ 1 m clear.","Cables/hoses routed overhead or protected; no trailing leads in walkways.","Segregate waste at source; label bins; hazardous waste in bunded, roofed store ≤ 90 days; manifest Form 10 to TSDF/recycler; Form 4 return by 30 June.","Used oil/oily rags/paint cans: hazardous; batteries to registered recycler (Battery Waste Rules 2022); e-waste to registered dismantler.","C&D waste: on-site segregation, reuse, transport to authorised processing facility with records; no dumping in lakes/drains/roadside (heavy fines in Bengaluru/Chennai).","Dust: suppression on roads/stockpiles, cover fine materials, speed limits, enclosures for cutting; AQ monitoring if required by EC.","Water: dewatering discharge through settlement; no silt to storm drains; rainwater harvesting; STP for camps.","Noise: timings, enclosures; community notice for night work with permission.","Sanitation: clean toilets daily, soap/water, waste collection, pest control; malaria/dengue prevention (no stagnant water).","Monthly environmental inspection; six-monthly EC compliance; Form V environmental statement by 30 Sept (where applicable)."],ppe:["Standard; gloves for waste handling"],stop:["Burning of waste","Hazardous waste in open/unlabelled","Discharge of silt/oil to drain"],records:["Waste manifests, authorisations, EC compliance reports, consent documents, water tests, camp inspection"],refs:{india:["IS 7969; HOWM Forms 1/3/4/8/9/10; TSDFs: Gummidipoondi & Virudhunagar (TN), Dobbaspet & Harohalli (KA); Form V by 30 Sep","Environment (C&D) Waste Management Rules 2025; Hazardous & Other Wastes Rules 2016; E-Waste (Management) Rules 2022; Battery Waste Management Rules 2022; Plastic Waste Rules 2016; Solid Waste Rules 2016; Bio-Medical Waste Rules 2016","Air Act, Water Act, EP Act, Noise Rules 2000, EIA 2006; OSH Code s.24 welfare; BOCW welfare rules"],ka:["KSPCB XGN portal; lake & buffer-zone norms (Bellandur, Varthur, Peenya); OCEMS for 17 categories; STP dual-piping reuse in Bengaluru","KSPCB consents; BBMP SWM bye-laws & C&D rules; Karnataka BOCW Rules welfare"],tn:["TNPCB OCMMS portal; ZLD for dyeing/bleaching/tannery clusters; G.O. Ms. 213 & 127 river buffer bans (Cauvery, Bhavani, Palar, Tamirabarani)","TNPCB; Greater Chennai Corporation C&D/SWM bye-laws; TN BOCW Rules welfare"],osha:["1926.25 housekeeping; 1926.250 storage; 1910.22; EPA RCRA (US)"],intl:["ISO 14001; UK Site Waste Management Plans; CDM 2015 Schedule 2 welfare"]},checklist:"cl-environment"},

{id:"health",t:"Occupational Health Surveillance, First Aid & Welfare",cat:"Health",tags:["Construction","Industrial","Chemical"],purpose:"Detect and prevent work-related ill health early; provide statutory medical, first-aid and welfare facilities.",scope:"Pre-employment and periodic medical examinations, dangerous-operations surveillance, first-aid boxes/rooms, ambulance, occupational health centre, drinking water, sanitation, canteen, crèche, rest rooms, labour accommodation, mental health.",roles:["Factory medical officer / certifying surgeon","First-aiders (certified)","Welfare officer (250+ workers)","Safety officer","HR"],hazards:["Undetected occupational disease (silicosis, NIHL, dermatitis, lead/solvent toxicity); heat illness; infectious disease in camps; fatigue; psychosocial stress"],pre:["Medical examination schedule per state rules dangerous-operations schedules and OSH Code (annual health examination for prescribed classes); Form numbers per state rules","First-aid: 1 box per 150 workers (verify state rule), contents per rule, trained first-aider per shift (≥ 1 per 150), ambulance room/OHC for 500+ workers (factory) or as rules; AED recommended","Welfare: drinking water (cool, potable, 1 point per 150), latrines/urinals (1 per 20–25 workers; separate for women), washing, rest shelter, canteen (100+ under OSH Code; 250+ under some state rules – verify), crèche (50+ workers under OSH Code), lunch room","Occupational health centre: part-time/full-time medical officer thresholds per state rules for hazardous units"],steps:["Pre-employment medical for all; fitness for specific tasks (height, confined space, crane, driver – vision/epilepsy screen).","Periodic exams per exposure (lead: blood lead 6-monthly; noise: audiometry annual; silica: CXR/spirometry per schedule); records in prescribed register.","Notify occupational diseases (OSH Code s.12; Third Schedule) by medical practitioner and employer.","First-aid boxes inspected weekly; register of treatments; first-aider list displayed.","Emergency medical: ambulance or vehicle on call 24×7; hospital tie-ups (trauma, burns, poison); transport time < 30 min.","Welfare inspections weekly (water quality tests monthly; toilets cleaned daily; camp hygiene).","Heat/cold/monsoon health advisories; vaccination drives where relevant (tetanus for injuries).","Mental health: fatigue management (hours, rest days), grievance channel, POSH committee, counselling access (ISO 45003).","Return-to-work after injury with modified duties; compensation coordination (ESI/EC).","Annual health report to safety committee; OHC statistics in annual return."],ppe:["N/A"],stop:["Medical unfitness for task","No first-aider on shift"],records:["Medical examination registers/certificates, first-aid register, OHC records, disease notifications, water tests, welfare inspection"],refs:{india:["IS 3103 industrial ventilation; IS 6665 industrial lighting; IS 10592 emergency showers/eyewash; Bio-Medical Waste Rules 2016 (OHC)","OSH Code 2020 s.6 (annual health exam), s.12 (notifiable diseases), s.24 (welfare), s.23 (welfare officer); OSH Central Rules 2026 (health exam, welfare standards)","Factories Act ss.11–20 (health), ss.42–50 (welfare), s.45 first aid – via state rules; BOCW Rules welfare & first aid; Code on Social Security (ESI medical)","Karnataka/TN Factories Rules dangerous-operations medical schedules; TN Rule 63-B first-aid training"],ka:["KA Rule 19 (ventilation/temperature); KA Rules 88-A–88-P (OHC, ambulance van)","Karnataka Factories Rules 1969 (first aid, OHC, welfare, medical exams); Karnataka BOCW Rules"],tn:["TN Rule 17 (ventilation/temperature); TN Rules 61-N/61-O/61-P (medical exams, OHC, ambulance van)","TN Factories Rules 1950 (first aid Rule 63-B, OHC, welfare, medical exams); TN BOCW Rules"],osha:["1910.151 / 1926.50 medical & first aid; 1910.141 sanitation; 1926.51; 1910.1020 access to medical/exposure records; 1910.1025(j), 1910.95(g) surveillance"],intl:["ILO C161 occupational health services; ISO 45003; UK Workplace (HSW) Regs 1992; CDM 2015 Schedule 2"]},checklist:"cl-welfare"},

{id:"committee",t:"Safety Governance – Safety Officer, Safety Committee, Audits & Legal Register",cat:"Management",tags:["Construction","Industrial","Chemical"],purpose:"Establish statutory governance: appointments, committee, audits, legal compliance monitoring and management review.",scope:"Factories, construction sites, MAH units, mines; corporate HSE management system (ISO 45001/14001).",roles:["Occupier/employer (ultimate responsibility; OSH Code s.6)","Site head / factory manager","Safety officer(s) – qualified per rules (degree/diploma in industrial safety; thresholds by headcount)","Safety committee (equal employer/worker representation; chaired by senior manager; meets at least quarterly – monthly on many sites)","Welfare officer; medical officer"],hazards:["Governance gaps found in audits/inspections; prosecutions of occupier/manager"],pre:["Appointment letters & notification to ICF (safety officer, manager/occupier particulars); qualification evidence","Safety committee constitution notified; minutes system","Legal register listing every applicable act/rule/consent/licence with renewal dates (Factories/OSH registration, fire NOC, CTE/CTO, HW authorisation, PESO licences, boiler certificates, lift licences, competent-person certificates, BOCW registration/cess, contractor licences, EC)","Audit plan: internal (ISO 45001 cl. 9.2), statutory safety audit (Karnataka Safety Audit Rules 2024; MSIHC Rule 12 annual for MAH; IS 14489), external certification"],steps:["Set OHS policy signed by top management; objectives & KPIs (leading/lagging).","Appoint safety officer(s) per threshold (OSH Code s.23: factory 500+, hazardous factory 250+, construction 250+ — verify rules) and welfare officer (250+); medical officer for hazardous units.","Constitute safety committee (OSH Code s.22) with worker representatives; meet quarterly minimum; track actions.","Maintain legal register; compliance evaluation quarterly; calendar of renewals, returns (annual return, Form V, HW Form 4, cess), and statutory tests (lifting 12 m, pressure vessels, hoists 6 m, extinguishers, earth pits, electrical inspection).","Inspections: daily supervisor, weekly safety officer, monthly management walk; findings tracked.","Audits: internal annually; statutory safety audit by recognised auditor as per rules; close findings with evidence.","Management review (ISO 45001 cl. 9.3) at least annually: performance, incidents, audits, legal changes (e.g. OSH state rules notification), resources.","Consultation & participation: safety committee, toolbox feedback, suggestion scheme, worker right to refuse unsafe work (OSH Code).","Document control: procedures, forms, records retention.","Report to board/corporate; benchmark with IS 3786 rates."],ppe:["N/A"],stop:["No safety officer where mandatory","Expired statutory certificate affecting safety (e.g. crane test)"],records:["Policy, appointments, committee minutes, legal register, audit reports, management review, inspection logs, statutory registers"],refs:{india:["IS 14489 audit benchmark for TN & KA statutory safety audits","OSH Code 2020 s.6, s.22, s.23, s.24; OSH Central Rules 2026 (Safety Officer duties, committee); Factories Act s.40B/41G legacy","Karnataka Factories (Safety Audit) Rules 2024; MSIHC Rule 12; IS 14489; IS 3786; BOCW rules (safety officer/committee for 500+)"],ka:["KA Rule 88-B Safety Committee; Karnataka Factories Safety Audit Rules 2024; MAH Control (Karnataka) Rules 1994","DFBISH notifications for safety officer qualifications; Karnataka Safety Audit Rules 2024"],tn:["TN CIMAH Rules 1994 third-party audits","TN Factories Rules safety officer rules (Rule 76-series – verify); DISH TN circulars"],osha:["OSHA Safety & Health Program Recommended Practices (2016); VPP; 1910.119 PSM audits every 3 years"],intl:["ISO 45001:2018 (cl. 5, 9, 10); ISO 14001; CDM 2015; ILO-OSH 2001; HSG65"]},checklist:"cl-statutory-factory"},

{id:"moc",t:"Management of Change (MoC)",cat:"Management",tags:["Chemical","Industrial","Construction"],purpose:"Ensure changes to process, equipment, chemicals, procedures, organisation or site layout are risk-assessed and communicated before implementation.",scope:"Permanent, temporary and emergency changes; 'replacement in kind' excluded; includes design changes on construction projects and temporary works alterations.",roles:["Change initiator","MoC coordinator","Reviewers (process, safety, electrical, environment)","Approver (site head)"],hazards:["Unreviewed changes causing incidents (e.g. bypassed trip, new solvent, altered scaffold); temporary changes becoming permanent"],pre:["MoC form and register; classification (minor/major); PHA trigger criteria; PSSR (pre-start-up safety review) checklist"],steps:["Describe change, technical basis, duration (temporary ≤ 90 days with removal date).","Risk assess: HAZOP/What-if as appropriate; environmental aspects; legal implications (consents, licences, MSIHC thresholds).","Update documents: P&IDs, procedures, SDS, training, emergency plan, drawings.","Approve at defined level; communicate to affected persons (training/toolbox).","PSSR before start-up: construction per design, procedures in place, training done, permits.","Close MoC after verification; temporary changes reverted or converted via new MoC.","Audit MoC compliance quarterly."],ppe:["N/A"],stop:["Change implemented without MoC"],records:["MoC register, risk assessments, PSSR, document updates"],refs:{india:["MSIHC Rule 10 (safety report update on modification); OSH Code Ch. XII; IS 15656; OISD-STD-163"],ka:["DFBISH MAH unit requirements"],tn:["DISH TN MAH unit requirements"],osha:["1910.119(l) MoC; 1910.119(i) PSSR"],intl:["ISO 45001 cl. 8.1.3; CCPS MoC guidelines; Seveso III"]},checklist:"cl-statutory-factory"},

{id:"pressure",t:"Pressure Systems, Boilers & Steam/Air Lines",cat:"Industrial",tags:["Industrial","Chemical"],purpose:"Prevent boiler/vessel explosions, steam burns and compressed-air injuries.",scope:"IBR boilers, steam pipelines, air receivers, autoclaves, heat exchangers, pressure vessels, compressors, hydro-testing, pneumatic testing.",roles:["Boiler operation engineer / attendant (certified)","Competent person (pressure vessel examination)","Maintenance"],hazards:["Low-water explosion; safety-valve failure; corrosion/thinning; pneumatic test energy; steam leaks; blowdown hazards"],pre:["Boiler registered; current certificate of inspection; IBR-approved repairs; attendant certificates; log sheets","Pressure vessels: examined by competent person (external every 6 months, internal 12 months, hydraulic test every 4 years – per state Factories Rules, verify); safety valves tested; gauges calibrated","Pneumatic testing only with written procedure, exclusion zone, and approval; hydro-test preferred"],steps:["Daily boiler checks: water level (gauge glass blowdown), safety valve lift test weekly, low-water cut-off test, flame failure, feedwater treatment.","Start-up/shutdown per written procedure; purge before ignition; no bypassing of interlocks.","Blowdown to blowdown vessel; valves operated in sequence; PPE for steam.","Isolate steam lines for maintenance by double block & bleed; drain condensate; lock; test cold.","Air receivers: drain daily, safety valve test, inspection per rules; never use air for cleaning body.","Record all tests in boiler log and vessel register; renew certificates before expiry.","Accident/explosion: stop, isolate, report to Chief Inspector of Boilers within 24 h; preserve scene."],ppe:["Face shield, heat-resistant gloves, FR clothing near steam; hearing protection"],stop:["Certificate expired","Safety valve inoperative","Water level not visible"],records:["Boiler certificates, log sheets, vessel examination reports, safety valve tests, operator certificates"],refs:{india:["Factories Act s.31 pressure plant; IS 2825","Boilers Act 2025; Indian Boiler Regulations 1950; Factories Act s.31 (pressure plant) via state rules (Rule 61 KA/TN); SMPV(U) Rules 2016; IS 2825 unfired pressure vessels; IS 7938 air receivers"],ka:["KA Rule 61 (Form 8): ultrasonic/hydrostatic certification of pressure vessels & air receivers; Rule 65-B thermic-fluid heaters & ovens; Karnataka Boiler Rules 1982","Karnataka Boiler Rules; DFBISH Boiler Inspectorate; Karnataka Factories Rules Rule 61"],tn:["TN Rule 56 (Form 8-A): external/internal exam 6–12 months, hydrostatic test 2–4 years; Rules 61-D/61-E ovens, driers, thermic-fluid heaters; TN Boiler Rules (Directorate of Boilers)","Director of Boilers TN; TN Factories Rules Rule 61"],osha:["1910.169 air receivers; ASME BPVC; NB-23 inspection code; 1910.119 (if HHCs)"],intl:["UK Pressure Systems Safety Regs 2000; PED 2014/68/EU; EN 13445"]},checklist:"cl-statutory-factory"},

{id:"radiography",t:"Industrial Radiography & NDT on Site",cat:"Industrial",tags:["Construction","Industrial"],purpose:"Prevent radiation exposure to workers and public during gamma/X-ray radiography of welds.",scope:"Ir-192/Co-60/Se-75 gamma projectors, X-ray units, nucleonic gauges, moisture-density gauges.",roles:["Radiological Safety Officer (AERB-certified)","Certified radiographers (Level I/II with RT certification)","Site safety officer (coordination)"],hazards:["Direct beam/scatter exposure; stuck source; theft/loss of source; non-radiography workers entering cordoned area"],pre:["AERB licence of agency; eLORA approval; source transport approval; survey meter calibrated; TLD badges & pocket dosimeters; collimator, source retrieval kit; emergency plan","Radiography permit on site (night/isolated preferred); cordon at 1 µSv/h (or AERB-specified), signage in local language, warning lights/sirens"],steps:["Plan exposure with radiography permit; notify adjacent contractors; schedule for minimum occupancy.","Set barriers and survey boundary with meter; post radiographers at approaches; siren before exposure.","Expose from maximum distance; verify source return with survey meter after each exposure; never approach without survey.","Keep source in pit/safe when not in use; two-person rule for custody; daily source inventory.","Emergency (stuck source): cordon larger, do not attempt retrieval unless trained, call RSO/AERB.","Dose records: TLD monthly; limit 20 mSv/yr; pregnant worker restrictions.","Dispose/return sources via AERB-approved route."],ppe:["Dosimeters (TLD + direct reading); standard PPE; lead screens not substitute for distance"],stop:["Survey meter faulty/uncalibrated","Non-radiography personnel inside cordon","Source not accounted"],records:["AERB licence, permits, dose records, source movement log, survey logs"],refs:{india:["Atomic Energy Act 1962; AERB e-LORA portal (industrial radiography, nucleonic gauges, X-ray baggage/quality scanners); IS 17893:2023 radiography permit","Atomic Energy (Radiation Protection) Rules 2004; AERB Safety Code for Industrial Radiography (AERB/RF-IR/SC-1); AERB RSO requirements; OSH Code s.6"],ka:["AERB (central); site permits"],tn:["AERB (central); site permits"],osha:["1910.1096 ionising radiation; 10 CFR Part 34 (NRC) industrial radiography"],intl:["IAEA Safety Standards SSG-11; UK Ionising Radiations Regs 2017"]},checklist:"cl-daily"},

{id:"night-lone",t:"Night Work, Lone Working & Women's Safety at Night",cat:"Management",tags:["Construction","Industrial"],purpose:"Control fatigue, visibility, security and emergency-response gaps during night shifts and lone work; meet statutory conditions for women on night shifts.",scope:"Night pours, road works, plant night shifts, security, remote maintenance, lone operators.",roles:["Shift in-charge","Security","HR (consents, transport)"],hazards:["Fatigue-related errors; poor lighting; reduced supervision/rescue; harassment/assault risk; animal/snake bites in remote sites"],pre:["Lighting ≥ 50 lux general / 100–200 lux task (IS 3646); portable towers; reflective PPE","Women night shift (OSH Code s.43 + state rules/Factories amendments): written consent, free transport with security guard and verified driver, CCTV, lighting, minimum batch size (state-specific), separate facilities, ICC under POSH Act 2013","Lone worker: check-in schedule (every 1–2 h), communication device, prohibited tasks alone (confined space, WAH, HT, hot work)","Shift roster limits: ≤ 48 h/week, 8–12 h/day with OT limits; rest ≥ 11 h between shifts (good practice)"],steps:["Plan night tasks: avoid high-risk work unless necessary; extra supervision; ERT/first-aider on each shift.","Brief workers on lighting, traffic, emergency numbers; night-shift toolbox talk.","Security patrols; gate control; anti-harassment reporting channel.","Fatigue: breaks every 2 h, caffeine policy, no double shifts, journey management for commuting.","Lone worker check-ins logged; escalation if missed.","Snake/insect: boots, torch, first-aid/antivenom nearby hospital identified.","Review incidents by shift."],ppe:["Hi-vis class 3, head torch"],stop:["Lone working on prohibited tasks","Transport/security not available for women night shift"],records:["Consents, transport logs, shift rosters, lone-worker check-in log"],refs:{india:["OSH Code 2020 s.43 (women night work with consent & conditions), s.25–s.27 (hours); POSH Act 2013; Factories (Karnataka Amendment) Act 2023; TN Shops Act night-work rules","State OSH rules/Factories rules conditions (transport, CCTV, batch size)"],ka:["Factories (Karnataka Amendment) Act 2023 conditions; Karnataka S&E Act 2026 amendment (driver verification, route planning)"],tn:["TN Factories Rules/TN Shops Act night-work conditions; DISH TN circulars"],osha:["General Duty Clause; 1926.56 illumination (5 fc general); NIOSH shift-work guidance"],intl:["UK Working Time Regs 1998; HSE lone working guidance INDG73; ILO C171 night work"]},checklist:"cl-night"}
];
